{"method":"get_file","path":"_ds/cmem-viewer-design-system-f9904b75-a739-4168-bb47-c0ababbb4185/tokens/colors.css","content":"/* cmem viewer — color tokens (themed)
   ---------------------------------------------------------------
   Four themes, switched via [data-theme] on <html> (or any ancestor):
     • light          — NEW default, clean neutral canvas, violet accent
     • dark           — NEW neutral dark
     • classic-light  — faithful to the original claude-mem viewer
                        (warm paper, GitHub-blue accent)
     • classic-dark   — original claude-mem dark (warm black, sky-blue accent)

   Accent is independent, switched via [data-accent] on <html>:
     blue · violet · jade · amber · rose · teal
   Each theme ships a sensible default accent; [data-accent] overrides it
   and retints links, focus rings, toggles, selected states & the primary
   accent action. Soft/strong steps are derived from the live --accent and
   --paper, so accents adapt to whatever theme is active.

   Components reference the raw palette tokens (--ink-*, --paper, --line-*,
   tint families, --violet-600 …) directly, so each theme redefines those.
   --------------------------------------------------------------- */

/* ============================================================ *
 *  THEME-INDEPENDENT MAPPING
 *  Semantic aliases + accent derivation. These resolve per-theme
 *  because the raw tokens & --accent they reference are theme-set.
 * ============================================================ */
:root, [data-theme] {
  /* accent steps derived from the active accent + active paper/ink */
  --accent-strong: color-mix(in srgb, var(--accent) 76%, var(--ink-1));
  --accent-soft:   color-mix(in srgb, var(--accent) 16%, var(--paper));
  --accent-line:   color-mix(in srgb, var(--accent) 42%, var(--paper));

  /* interactive accent — toggles, selected chips, links, focus */
  --violet-600: var(--accent);
  --violet-700: var(--accent-strong);

  /* semantic surface / text / line aliases */
  --surface-app:        var(--canvas);
  --surface-card:       var(--paper);
  --surface-well:       var(--canvas-deep);
  --surface-active-nav: var(--accent-soft);

  --text-body:  var(--ink-1);
  --text-muted: var(--ink-2);
  --text-faint: var(--ink-3);
  --text-link:  var(--accent);

  --action-affirm: var(--jade-500);
  --action-accent: var(--accent);

  --border-input: var(--line-2);
  --border-card:  var(--line-1);
  --focus-ring:   var(--accent);
}

/* ============================================================ *
 *  THEME: LIGHT (new default) — neutral, crisp, violet accent
 * ============================================================ */
:root,
[data-theme="light"] {
  color-scheme: light;
  --accent: #6d3fc8;

  /* ink */
  --ink-1: #1a1a1f;
  --ink-2: #56565f;
  --ink-3: #97979f;
  --ink-inverse: #ffffff;

  /* surfaces */
  --paper: #ffffff;
  --canvas: #f7f7f9;
  --canvas-deep: #eeeef2;
  --scrim: rgba(20, 20, 26, 0.42);

  /* lines */
  --line-1: #e9e9ee;
  --line-2: #dadae1;
  --line-dashed: #cacad2;

  /* tint family — prompt(lilac) / summary(butter) / observation(sky) / success(mint) / warm(peach) */
  --lilac-100: #f1ecfb; --lilac-200: #e4dbf7; --lilac-300: #cfc0f0;
  --mint-100:  #e6f4ec; --mint-200:  #cfe9da;
  --peach-100: #fbeede; --peach-200: #f6e0c6;
  --butter-100:#fbf2d6; --butter-200:#f5e3a6;
  --sky-100:   #e8f1fb; --sky-200:   #d4e4f6;

  /* semantic card hues (text/border on tints) */
  --jade-500: #1f9d6b; --jade-600: #178055;
  --green-700: #1b7f4d;
  --amber-800: #8a5a16;
  --navy-700:  #1f3a66;
  --red-600:   #d23f3f;
  --blue-600:  #2f6fd2;
  --type-prompt: #8250df;   /* prompt-card hue, independent of accent */

  /* primary action (DS black-pill identity) */
  --action-primary:       #1a1a1f;
  --action-primary-hover: #2e2c36;
  --action-on-primary:    #ffffff;

  --shadow-card:   0 1px 2px rgba(20, 20, 26, 0.05);
  --shadow-raised: 0 4px 16px rgba(20, 20, 26, 0.09);
  --shadow-modal:  0 24px 64px rgba(20, 20, 26, 0.20);
}

/* ============================================================ *
 *  THEME: DARK (new) — neutral charcoal, lifted violet accent
 * ============================================================ */
[data-theme="dark"] {
  color-scheme: dark;
  --accent: #9a7ce8;

  --ink-1: #ecebf0;
  --ink-2: #a6a5b0;
  --ink-3: #6f6e7a;
  --ink-inverse: #16151b;

  --paper: #1b1a20;
  --canvas: #131217;
  --canvas-deep: #0d0c11;
  --scrim: rgba(0, 0, 0, 0.62);

  --line-1: #2a2932;
  --line-2: #3a3943;
  --line-dashed: #45444f;

  --lilac-100: #241e33; --lilac-200: #2f2742; --lilac-300: #3c3354;
  --mint-100:  #15271d; --mint-200:  #1d3628;
  --peach-100: #2a2218; --peach-200: #382d1e;
  --butter-100:#2a2410; --butter-200:#383016;
  --sky-100:   #141f30; --sky-200:   #1c2a40;

  --jade-500: #38c08a; --jade-600: #2da877;
  --green-700: #5fcf94;
  --amber-800: #d4b888;
  --navy-700:  #a8b8c8;
  --red-600:   #e7767f;
  --blue-600:  #79b8ff;
  --type-prompt: #b9a6e8;

  --action-primary:       #ecebf0;
  --action-primary-hover: #d6d4df;
  --action-on-primary:    #18171e;

  --shadow-card:   0 1px 2px rgba(0, 0, 0, 0.40);
  --shadow-raised: 0 6px 20px rgba(0, 0, 0, 0.50);
  --shadow-modal:  0 24px 64px rgba(0, 0, 0, 0.62);
}

/* ============================================================ *
 *  THEME: CLASSIC LIGHT — original claude-mem viewer
 *  warm paper canvas, GitHub-blue accent, gold/purple/blue cards
 * ============================================================ */
[data-theme="classic-light"] {
  color-scheme: light;
  --accent: #0969da;

  --ink-1: #2b2520;
  --ink-2: #5a5248;
  --ink-3: #8f8a7e;
  --ink-inverse: #ffffff;

  --paper: #ffffff;
  --canvas: #efebe4;
  --canvas-deep: #e6e1d8;
  --scrim: rgba(43, 37, 32, 0.44);

  --line-1: #d8dee4;
  --line-2: #d0d7de;
  --line-dashed: #cbc6bb;

  --lilac-100: #f6f3fb; --lilac-200: #ece5f8; --lilac-300: #d9ccf2;
  --mint-100:  #eaf4ec; --mint-200:  #d6ecdb;
  --peach-100: #fdf1e3; --peach-200: #f8e3cb;
  --butter-100:#fffbf0; --butter-200:#fbefc4;
  --sky-100:   #f0f6fb; --sky-200:   #dcebf8;

  --jade-500: #1a7f37; --jade-600: #15722f;
  --green-700: #1a7f37;
  --amber-800: #8a6116;
  --navy-700:  #1f3a66;
  --red-600:   #d1242f;
  --blue-600:  #0550ae;
  --type-prompt: #8250df;

  /* classic primary button = solid GitHub blue with white text */
  --action-primary:       #0969da;
  --action-primary-hover: #0860ca;
  --action-on-primary:    #ffffff;

  --shadow-card:   0 1px 2px rgba(43, 37, 32, 0.06);
  --shadow-raised: 0 4px 16px rgba(43, 37, 32, 0.10);
  --shadow-modal:  0 24px 64px rgba(43, 37, 32, 0.20);
}

/* ============================================================ *
 *  THEME: CLASSIC DARK — original claude-mem dark
 *  warm-black canvas, sky-blue accent
 * ============================================================ */
[data-theme="classic-dark"] {
  color-scheme: dark;
  --accent: #58a6ff;

  --ink-1: #dcd6cc;
  --ink-2: #b8b0a4;
  --ink-3: #938a7e;
  --ink-inverse: #1a1916;

  --paper: #252320;
  --canvas: #1a1916;
  --canvas-deep: #15140f;
  --scrim: rgba(0, 0, 0, 0.60);

  --line-1: #3a3834;
  --line-2: #45423d;
  --line-dashed: #4a4540;

  --lilac-100: #262033; --lilac-200: #302947; --lilac-300: #3d3458;
  --mint-100:  #18271d; --mint-200:  #203628;
  --peach-100: #2c2419; --peach-200: #3a2f20;
  --butter-100:#2a2724; --butter-200:#3a3320;
  --sky-100:   #1a2332; --sky-200:   #223047;

  --jade-500: #3fb950; --jade-600: #35a046;
  --green-700: #56d364;
  --amber-800: #d4b888;
  --navy-700:  #a8b8c8;
  --red-600:   #e74856;
  --blue-600:  #79b8ff;
  --type-prompt: #9e8ccc;

  /* classic dark primary button stays solid blue */
  --action-primary:       #0969da;
  --action-primary-hover: #1177e6;
  --action-on-primary:    #ffffff;

  --shadow-card:   0 1px 2px rgba(0, 0, 0, 0.45);
  --shadow-raised: 0 6px 20px rgba(0, 0, 0, 0.55);
  --shadow-modal:  0 24px 64px rgba(0, 0, 0, 0.65);
}

/* ============================================================ *
 *  ACCENT PALETTE  — one base hue each; steps derived in the
 *  mapping block. Declared LAST so [data-accent] overrides each
 *  theme's default --accent regardless of cascade position.
 * ============================================================ */
[data-accent="blue"]   { --accent: #2f6fd2; }
[data-accent="violet"] { --accent: #6d3fc8; }
[data-accent="jade"]   { --accent: #1f9d6b; }
[data-accent="amber"]  { --accent: #c2820a; }
[data-accent="rose"]   { --accent: #d2436b; }
[data-accent="teal"]   { --accent: #0f8fa6; }
