input.content:
/* cmem viewer — spacing, radii, shadows, motion */

:root {
  /* Spacing — 4px base */
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 12px;
  --space-4: 16px;
  --space-5: 20px;
  --space-6: 24px;
  --space-8: 32px;
  --space-10: 40px;
  --space-12: 48px;
  --space-16: 64px;

  /* Radii — pill-forward system */
  --radius-pill: 999px;     /* buttons, badges, search, nav items, chips */
  --radius-card: 16px;      /* cards, panels */
  --radius-card-lg: 20px;   /* hero cards, modals */
  --radius-input: 12px;     /* text inputs, textareas */
  --radius-thumb: 12px;     /* thumbnails, logo tiles */
  --radius-tile: 8px;       /* small choice tiles */

  /* Shadows — near-flat; depth comes from borders + canvas contrast */
  --shadow-card: 0 1px 2px rgba(24, 24, 28, 0.04);
  --shadow-raised: 0 4px 16px rgba(24, 24, 28, 0.08);
  --shadow-modal: 0 24px 64px rgba(24, 24, 28, 0.18);

  /* Motion — quick, quiet, no bounce */
  --ease-out: cubic-bezier(0.16, 1, 0.3, 1); /* @kind other */
  --duration-fast: 120ms; /* @kind other */
  --duration-base: 200ms; /* @kind other */
  --duration-slow: 320ms; /* @kind other */
}

