/* cmem viewer — webfonts
   Brand font: Signat (self-hosted, .otf). Spline Sans Mono (Google) covers
   timestamps / memory IDs. Signat ships weights 100–900; we self-host the
   400–800 range the product uses, plus a regular italic. */

@import url("https://fonts.googleapis.com/css2?family=Spline+Sans+Mono:wght@400;500&display=swap");

@font-face {
  font-family: "Signat";
  src: url("../assets/fonts/Signat-regular.otf") format("opentype");
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: "Signat";
  src: url("../assets/fonts/Signat-regularitalic.otf") format("opentype");
  font-weight: 400;
  font-style: italic;
  font-display: swap;
}
@font-face {
  font-family: "Signat";
  src: url("../assets/fonts/Signat-medium.otf") format("opentype");
  font-weight: 500;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: "Signat";
  src: url("../assets/fonts/Signat-semibold.otf") format("opentype");
  font-weight: 600;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: "Signat";
  src: url("../assets/fonts/Signat-bold.otf") format("opentype");
  font-weight: 700;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: "Signat";
  src: url("../assets/fonts/Signat-extrabold.otf") format("opentype");
  font-weight: 800;
  font-style: normal;
  font-display: swap;
}

