await page.setViewport({ width: 390, height: 844, deviceScaleFactor: 2 });
await new Promise(r => setTimeout(r, 1500));
await page.screenshot({ path: `${OUT}/design-mobile.png` });

await browser.close();
console.log('done');
EOF
