26	// hex -> rgba; used to derive translucent coral tint/soft selection surfaces in
27	// dark mode (a wash of the accent rather than an opaque brown block)
28	function hexA(hex: string, a: number): string {
29	  const h = String(hex).replace('#', '');
30	  const f = h.length === 3 ? h.replace(/./g, (c) => c + c) : h;
31	  const n = parseInt(f, 16);
32	  return `rgba(${(n >> 16) & 255}, ${(n >> 8) & 255}, ${n & 255}, ${a})`;
33	}
