38	function buildTimeline(data: ViewerData, filters: Filters): DayEntry[] {
39	  const { project, types, concepts, file } = filters;
40	  const obsMatch = (o: ViewerData['observations'][number]) => {
41	    if (project && o.project !== project) return false;
42	    if (types.length && !types.includes(o.type)) return false;
43	    if (concepts.length && !o.concepts.some((c) => concepts.includes(c))) return false;
44	    if (file && !(o.files_read.includes(file) || o.files_modified.includes(file))) return false;
45	    return true;
46	  };
47	
48	  const bySession: Record<string, ViewerData['observations']> = {};
49	  data.observations.filter(obsMatch).forEach((o) => {
50	    (bySession[o.session_id] = bySession[o.session_id] || []).push(o);
51	  });
52	
53	  const promptBySession = Object.fromEntries(data.prompts.map((p) => [p.session_id, p]));
54	  const groups = data.sessions
55	    .filter((s) => bySession[s.id])
56	    .map((s) => ({
57	      session: s,
58	      prompt: promptBySession[s.id],
59	      observations: bySession[s.id].sort((a, b) => a.at - b.at),
60	    }));
61	
62	  const byDay: Record<string, typeof groups> = {};
63	  groups.forEach((g) => {
64	    const key = fmtDayKey(g.session.started);
65	    (byDay[key] = byDay[key] || []).push(g);
66	  });
67	
68	  return Object.entries(byDay)
69	    .map(([key, sessions]) => ({
70	      key,
71	      epoch: sessions[0].session.started,
72	      sessions: sessions.sort((a, b) => b.session.started - a.session.started),
73	    }))
74	    .sort((a, b) => b.epoch - a.epoch);
75	}
