137	// ---------- file tree ----------
138	interface FileInfo { count: number; modified: boolean }
139	interface TreeFile extends FileInfo { path: string; name: string }
140	interface TreeNode { dirs: Record<string, TreeNode>; files: TreeFile[] }
141	
142	function buildFileTree(entries: [string, FileInfo][]): TreeNode {
143	  const root: TreeNode = { dirs: {}, files: [] };
144	  entries.forEach(([path, info]) => {
145	    // drop empty segments so absolute paths don't create a nameless root dir
146	    const parts = path.split('/').filter(Boolean);
147	    if (!parts.length) return;
148	    let node = root;
149	    parts.slice(0, -1).forEach((seg) => {
150	      node = node.dirs[seg] = node.dirs[seg] || { dirs: {}, files: [] };
151	    });
152	    node.files.push({ path, name: parts[parts.length - 1], ...info });
153	  });
154	  return root;
155	}
156	
157	function treeCount(node: TreeNode): number {
158	  let n = node.files.reduce((s, f) => s + f.count, 0);
159	  Object.values(node.dirs).forEach((d) => { n += treeCount(d); });
160	  return n;
161	}
