171	}) {
172	  const dirNames = Object.keys(node.dirs).sort();
173	  const files = [...node.files].sort((a, b) => a.name.localeCompare(b.name));
174	  return (
175	    <>
176	      {dirNames.map((name) => {
177	        const dirPath = prefix + name;
178	        const isClosed = !!closed[dirPath];
179	        const child = node.dirs[name];
