499	      const min = obs.reduce((m, o) => Math.min(m, o.at), Infinity);
500	      const max = obs.reduce((m, o) => Math.max(m, o.at), -Infinity);
501	      range = fmt(min) === fmt(max) ? fmt(max) : `${fmt(min)} – ${fmt(max)}`;
502	    }
503	    return { mem: obs.length, sessions: sess.size, files: files.size, range };
504	  }, [data, filters.project]);
505	
506	  const ctxGroup = React.useMemo(() => {
