'use client';

// ============================================================
// cmem cloud viewer — app shell: header, chips bar, files drawer,
// date rail, timeline assembly, notes, ask-your-agent.
// The first-class cloud memory viewer.
// (ported from cmem-viewer-pro/cmem-viewer/app-v5.jsx, rewired to
//  the cloud data source and native React)
// ============================================================
import * as React from 'react';
import './cloud-viewer.css';
import { Icon, TYPE_META, fmtTime, fmtDayKey, fmtDayLabel } from './format';
import { Timeline } from './Timeline';
import { useCloudData } from './useCloudData';
import { useTweaks, useTheme, ThemeToggle, SettingsMenu, ACCENTS } from './HeaderControls';
import {
  SearchBar, AgentToasts, AnswerDrawer, useAgentSessions, useNotes,
  type AgentSession,
} from './SearchAgent';
import type {
  ViewerData, Filters, Note, DayEntry, Tweaks, LiveState,
} from './types';

const LOGO = '/cmem-viewer-logo.jpg';

// hex -> rgba; used to derive translucent coral tint/soft selection surfaces in
// dark mode (a wash of the accent rather than an opaque brown block)
function hexA(hex: string, a: number): string {
  const h = String(hex).replace('#', '');
  const f = h.length === 3 ? h.replace(/./g, (c) => c + c) : h;
  const n = parseInt(f, 16);
  return `rgba(${(n >> 16) & 255}, ${(n >> 8) & 255}, ${n & 255}, ${a})`;
}

const VIEWER_TWEAK_DEFAULTS: Tweaks = { density: 'cozy', accent: '#FF6B47', roundness: 1 };

// ---------- data shaping ----------
function buildTimeline(data: ViewerData, filters: Filters): DayEntry[] {
  const { project, types, concepts, file } = filters;
  const obsMatch = (o: ViewerData['observations'][number]) => {
    if (project && o.project !== project) return false;
    if (types.length && !types.includes(o.type)) return false;
    if (concepts.length && !o.concepts.some((c) => concepts.includes(c))) return false;
    if (file && !(o.files_read.includes(file) || o.files_modified.includes(file))) return false;
    return true;
  };

  const bySession: Record<string, ViewerData['observations']> = {};
  data.observations.filter(obsMatch).forEach((o) => {
    (bySession[o.session_id] = bySession[o.session_id] || []).push(o);
  });

  const promptBySession = Object.fromEntries(data.prompts.map((p) => [p.session_id, p]));
  const groups = data.sessions
    .filter((s) => bySession[s.id])
    .map((s) => ({
      session: s,
      prompt: promptBySession[s.id],
      observations: bySession[s.id].sort((a, b) => a.at - b.at),
    }));

  const byDay: Record<string, typeof groups> = {};
  groups.forEach((g) => {
    const key = fmtDayKey(g.session.started);
    (byDay[key] = byDay[key] || []).push(g);
  });

  return Object.entries(byDay)
    .map(([key, sessions]) => ({
      key,
      epoch: sessions[0].session.started,
      sessions: sessions.sort((a, b) => b.session.started - a.session.started),
    }))
    .sort((a, b) => b.epoch - a.epoch);
}

// ---------- chips bar ----------
function ChipsBar({ data, filters, setFilters }: {
  data: ViewerData;
  filters: Filters;
  setFilters: React.Dispatch<React.SetStateAction<Filters>>;
}) {
  const conceptCounts = React.useMemo(() => {
    const m = new Map<string, number>();
    data.observations.forEach((o) => {
      if (filters.project && o.project !== filters.project) return;
      o.concepts.forEach((c) => m.set(c, (m.get(c) || 0) + 1));
    });
    return [...m.entries()].sort((a, b) => b[1] - a[1]);
  }, [data, filters.project]);

  const toggleType = (t: string) => setFilters((f) => ({
    ...f, types: f.types.includes(t) ? f.types.filter((x) => x !== t) : [...f.types, t],
  }));
  const toggleConcept = (c: string) => setFilters((f) => ({
    ...f, concepts: f.concepts.includes(c) ? f.concepts.filter((x) => x !== c) : [...f.concepts, c],
  }));

  const anyActive = filters.types.length > 0 || filters.concepts.length > 0;

  return (
    <div className="chips-bar">
      <div className="chips-scroll">
        {Object.entries(TYPE_META).map(([t, m]) => {
          const active = filters.types.includes(t);
          return (
            <button
              key={t}
              data-type={t}
              className={`type-chip${active ? ' active' : ''}`}
              onClick={() => toggleType(t)}
            >
              <Icon name={m.icon} size={13} />{m.label}
            </button>
          );
        })}
        <span className="chips-divider"></span>
        {conceptCounts.map(([c, n]) => (
          <button
            key={c}
            className={`concept-chip bar${filters.concepts.includes(c) ? ' active' : ''}`}
            onClick={() => toggleConcept(c)}
          >
            {c}<span className="chip-count">{n}</span>
          </button>
        ))}
        {anyActive && (
          <button className="chips-clear" onClick={() => setFilters((f) => ({ ...f, types: [], concepts: [] }))}>
            <Icon name="x" size={12} /> clear
          </button>
        )}
      </div>
    </div>
  );
}

// ---------- file tree ----------
interface FileInfo { count: number; modified: boolean }
interface TreeFile extends FileInfo { path: string; name: string }
interface TreeNode { dirs: Record<string, TreeNode>; files: TreeFile[] }

function buildFileTree(entries: [string, FileInfo][]): TreeNode {
  const root: TreeNode = { dirs: {}, files: [] };
  entries.forEach(([path, info]) => {
    // drop empty segments so absolute paths don't create a nameless root dir
    const parts = path.split('/').filter(Boolean);
    if (!parts.length) return;
    let node = root;
    parts.slice(0, -1).forEach((seg) => {
      node = node.dirs[seg] = node.dirs[seg] || { dirs: {}, files: [] };
    });
    node.files.push({ path, name: parts[parts.length - 1], ...info });
  });
  return root;
}

function treeCount(node: TreeNode): number {
  let n = node.files.reduce((s, f) => s + f.count, 0);
  Object.values(node.dirs).forEach((d) => { n += treeCount(d); });
  return n;
}

function TreeLevel({ node, depth, prefix, closed, onToggleDir, activeFile, onFile }: {
  node: TreeNode;
  depth: number;
  prefix: string;
  closed: Record<string, boolean>;
  onToggleDir: (p: string) => void;
  activeFile: string | null;
  onFile: (f: string) => void;
}) {
  const dirNames = Object.keys(node.dirs).sort();
  const files = [...node.files].sort((a, b) => a.name.localeCompare(b.name));
  return (
    <>
      {dirNames.map((name) => {
        const dirPath = prefix + name;
        const isClosed = !!closed[dirPath];
        const child = node.dirs[name];
        return (
          <React.Fragment key={dirPath}>
            <button
              className="tree-dir"
              style={{ paddingLeft: 8 + depth * 16 }}
              onClick={() => onToggleDir(dirPath)}
              aria-expanded={!isClosed}
            >
              <Icon name="chevronDown" size={12} className={`tree-caret${isClosed ? ' closed' : ''}`} />
              <Icon name="folder" size={13} className="tree-dir-glyph" />
              <span className="tree-dir-name">{name}</span>
              {isClosed && <span className="file-row-count">{treeCount(child)}</span>}
            </button>
            {!isClosed && (
              <TreeLevel
                node={child} depth={depth + 1} prefix={`${dirPath}/`}
                closed={closed} onToggleDir={onToggleDir}
                activeFile={activeFile} onFile={onFile}
              />
            )}
          </React.Fragment>
        );
      })}
      {files.map((f) => {
        const active = activeFile === f.path;
        return (
          <button
            key={f.path}
            className={`file-row tree-file${active ? ' active' : ''}`}
            style={{ paddingLeft: 8 + depth * 16 + 18 }}
            title={f.path}
            onClick={() => onFile(f.path)}
          >
            <Icon name={f.modified ? 'pencil' : 'eye'} size={12} className="file-row-glyph" />
            <span className="file-row-name">{f.name}</span>
            <span className="file-row-count">{f.count}</span>
          </button>
        );
      })}
    </>
  );
}

// ---------- sticky notes ----------
const NOTE_PAPERS = ['#FFE6A6', '#FFD3C2', '#D2E9D2', '#CFE0F4', '#F6DCEB'];
const NOTE_ROTS = [-1.8, 1.5, -0.9, 1.9, -1.3, 0.8];
function noteHash(id: string): number {
  let s = 0; const str = String(id);
  for (let i = 0; i < str.length; i++) s = (s * 31 + str.charCodeAt(i)) >>> 0;
  return s;
}

function StickyNote({ note, pinned, compact, onOpen, onPin, onDelete }: {
  note: Note;
  pinned: boolean;
  compact?: boolean;
  onOpen: () => void;
  onPin?: () => void;
  onDelete?: () => void;
}) {
  const h = noteHash(note.id);
  const paper = NOTE_PAPERS[h % NOTE_PAPERS.length];
  const rot = NOTE_ROTS[h % NOTE_ROTS.length];
  const preview = (note.blocks.find((b) => b.kind === 'p') || {}).text || '';
  const day = fmtDayLabel(note.created);
  const when = (day.lead === 'Today' || day.lead === 'Yesterday') ? day.lead : day.rest;
  return (
    <div
      className={`sticky-note${compact ? ' compact' : ''}`}
      style={{ '--note-paper': paper, '--note-rot': `${rot}deg` } as React.CSSProperties}
    >
      {pinned
        ? <span className="note-pin" aria-hidden="true"></span>
        : <span className="note-tape" aria-hidden="true"></span>}
      <button className="note-open" onClick={onOpen}>
        <span className="note-title">{note.title}</span>
        {preview && <span className="note-preview">{preview}</span>}
        <span className="note-meta">{when}<span className="note-sep">·</span>{note.cited.length} cited</span>
      </button>
      <div className="note-actions">
        {onPin && (
          <button
            className={`note-act${pinned ? ' on' : ''}`}
            onClick={onPin}
            title={pinned ? 'Unpin from top' : 'Pin to top'}
            aria-label={pinned ? 'Unpin from top' : 'Pin to top'}
          >
            <Icon name="bookmark" size={14} />
          </button>
        )}
        {onDelete && (
          <button className="note-act danger" onClick={onDelete} title="Delete note" aria-label="Delete note">
            <Icon name="trash" size={14} />
          </button>
        )}
      </div>
    </div>
  );
}

function NotesBoard({ notes, onOpen, onTogglePin, onDelete }: {
  notes: Note[];
  onOpen: (id: string) => void;
  onTogglePin: (id: string) => void;
  onDelete: (id: string) => void;
}) {
  return (
    <div className="notes-board">
      {notes.length === 0 ? (
        <p className="notes-empty">Ask your agent something, then save the answer — it lands here as a sticky note you can pin to the top.</p>
      ) : (
        notes.map((n) => (
          <StickyNote
            key={n.id} note={n} pinned={!!n.pinned}
            onOpen={() => onOpen(n.id)}
            onPin={() => onTogglePin(n.id)}
            onDelete={() => onDelete(n.id)}
          />
        ))
      )}
    </div>
  );
}

// pinned-notes slider docked to the top of the board
function PinnedRail({ notes, onOpen, onTogglePin }: {
  notes: Note[];
  onOpen: (id: string) => void;
  onTogglePin: (id: string) => void;
}) {
  const pinned = notes.filter((n) => n.pinned);
  if (pinned.length === 0) return null;
  return (
    <section className="pinned-rail" data-screen-label="Pinned notes">
      <div className="pinned-rail-head">
        <span className="pinned-rail-label"><Icon name="bookmark" size={12} /> Pinned</span>
        <span className="pinned-rail-count">{pinned.length}</span>
        <span className="pinned-rail-hint">{pinned.length > 2 ? 'scroll for more →' : 'pinned from your notes'}</span>
      </div>
      <div className="pinned-track">
        {pinned.map((n) => (
          <StickyNote
            key={n.id} note={n} pinned compact
            onOpen={() => onOpen(n.id)}
            onPin={() => onTogglePin(n.id)}
          />
        ))}
      </div>
    </section>
  );
}

// ---------- left page-sliding file drawer ----------
function FilesPanel({ data, filters, setFilters, live, active, onClose }: {
  data: ViewerData;
  filters: Filters;
  setFilters: React.Dispatch<React.SetStateAction<Filters>>;
  live: LiveState;
  active: boolean;
  onClose: () => void;
}) {
  const [closedDirs, setClosedDirs] = React.useState<Record<string, boolean>>({});
  const fileCounts = React.useMemo(() => {
    const m = new Map<string, FileInfo>();
    data.observations.forEach((o) => {
      if (filters.project && o.project !== filters.project) return;
      const touched = new Set([...o.files_read, ...o.files_modified]);
      touched.forEach((f) => {
        const e = m.get(f) || { count: 0, modified: false };
        e.count += 1;
        if (o.files_modified.includes(f)) e.modified = true;
        m.set(f, e);
      });
    });
    return [...m.entries()];
  }, [data, filters.project]);

  const tree = React.useMemo(() => buildFileTree(fileCounts), [fileCounts]);

  return (
    <aside className="file-drawer" data-screen-label="Files drawer" aria-hidden={!active}>
      <div className="dp-head">
        <span className="dp-glyph"><Icon name="folder" size={17} /></span>
        <div className="dp-head-text">
          <p className="dp-eyebrow">Browse memory</p>
          <h3 className="dp-title">Files</h3>
        </div>
        <span className="dp-count">{fileCounts.length}</span>
        <button className="icon-btn" onClick={onClose} aria-label="Close files"><Icon name="x" size={16} /></button>
      </div>
      <div className="dp-body">
        <div className="file-list">
          <TreeLevel
            node={tree} depth={0} prefix=""
            closed={closedDirs}
            onToggleDir={(p) => setClosedDirs((c) => ({ ...c, [p]: !c[p] }))}
            activeFile={filters.file}
            onFile={(f) => setFilters((fl) => ({ ...fl, file: fl.file === f ? null : f }))}
          />
        </div>
      </div>
      <div className="dp-foot">
        <Icon name="database" size={13} />
        {live.isLive ? (
          <span>
            <strong>{data.observations.length.toLocaleString()}</strong> loaded
            {live.total != null && live.total > data.observations.length && (
              <> of <span className="mono-inline">{live.total.toLocaleString()}</span></>
            )} · live
          </span>
        ) : (
          <span><strong>{data.observations.length.toLocaleString()}</strong> memories</span>
        )}
        <span className={`sync-dot${live.isLive ? '' : ' off'}`} style={{ marginLeft: 'auto' }}></span>
      </div>
    </aside>
  );
}

// ---------- right page-sliding sticky-notes drawer ----------
function NotesPanel({ notes, active, onClose, onOpen, onTogglePin, onDelete }: {
  notes: Note[];
  active: boolean;
  onClose: () => void;
  onOpen: (id: string) => void;
  onTogglePin: (id: string) => void;
  onDelete: (id: string) => void;
}) {
  const pinnedCount = notes.filter((n) => n.pinned).length;
  return (
    <aside className="notes-drawer" data-screen-label="Notes drawer" aria-hidden={!active}>
      <div className="dp-head">
        <span className="dp-glyph"><Icon name="stickyNote" size={17} /></span>
        <div className="dp-head-text">
          <p className="dp-eyebrow">{pinnedCount > 0 ? `${pinnedCount} pinned to top` : 'Pin to dock at top'}</p>
          <h3 className="dp-title">Notes</h3>
        </div>
        <span className="dp-count">{notes.length}</span>
        <button className="icon-btn" onClick={onClose} aria-label="Close notes"><Icon name="x" size={16} /></button>
      </div>
      <div className="dp-body">
        <NotesBoard notes={notes} onOpen={onOpen} onTogglePin={onTogglePin} onDelete={onDelete} />
