// ---------- date rail ----------
function DateRail({ days, activeKey, onJump }: {
  days: DayEntry[];
  activeKey: string | null;
  onJump: (key: string) => void;
}) {
  if (days.length === 0) return null;
  return (
    <nav className="date-rail" aria-label="Jump to a day" data-screen-label="Date rail">
      {days.map((d) => {
        const label = fmtDayLabel(d.epoch);
        const date = new Date(d.epoch * 1000);
        const lead = label.lead === 'Today' ? 'Today' : date.toLocaleDateString([], { weekday: 'short' });
        const n = d.sessions.reduce((m, g) => m + g.observations.length, 0);
        const active = activeKey === d.key;
        return (
          <button
            key={d.key}
            className={`rail-day${active ? ' active' : ''}`}
            onClick={() => onJump(d.key)}
            title={`${label.lead} — ${label.rest} · ${n}${n === 1 ? ' memory' : ' memories'}`}
            aria-current={active ? 'date' : undefined}
          >
            <span className="rail-lead">{lead}</span>
            <span className="rail-date">{date.toLocaleDateString([], { month: 'short', day: 'numeric' })}</span>
            <span className="rail-count">{n}</span>
          </button>
        );
      })}
    </nav>
  );
}

// ---------- app ----------
export function CloudViewer({ onConnect, onDevices, userId }: { onConnect?: () => void; onDevices?: () => void; userId?: string | null } = {}) {
  const live = useCloudData();
  const data = live.data;
  const [t, setTweak] = useTweaks(VIEWER_TWEAK_DEFAULTS);
  const [theme, setTheme, resolvedTheme] = useTheme();
  const dark = resolvedTheme === 'dark';
  const accent = Object.values(ACCENTS).find((a) => a.a === t.accent) || ACCENTS.coral;

  const [filters, setFilters] = React.useState<Filters>({ project: '', types: [], concepts: [], file: null });
  const [openDays, setOpenDays] = React.useState<Record<string, boolean> | null>(null);
  const [openSessions, setOpenSessions] = React.useState<Record<string, boolean> | null>(null);
  const [openObs, setOpenObs] = React.useState<Record<string, boolean>>({});
  const [drawer, setDrawer] = React.useState<{ type: 'agent' | 'note'; id: string } | null>(null);
  const [panel, setPanel] = React.useState<'files' | 'notes' | null>(null);
  const [activeDayKey, setActiveDayKey] = React.useState<string | null>(null);
  const [ctxSessionId, setCtxSessionId] = React.useState<string | null>(null);
  const [flashId, setFlashId] = React.useState<number | string | null>(null);
  const [savedMap, setSavedMap] = React.useState<Record<string, boolean>>({});

  const agent = useAgentSessions(data);
  const { notes, saveNote, deleteNote, togglePin } = useNotes(data.seedNotes, userId);

  const days = React.useMemo(() => buildTimeline(data, filters), [data, filters]);
  const projects = React.useMemo(
    () => [...new Set([...data.sessions.map((s) => s.project), ...(live.streamProjects || [])])].sort(),
    [data, live.streamProjects],
  );
  const citedObs = React.useMemo(() => Object.fromEntries(data.observations.map((o) => [o.id, o])), [data]);

  // project header stats (project filter only)
  const projStats = React.useMemo(() => {
    const obs = data.observations.filter((o) => !filters.project || o.project === filters.project);
    const sess = new Set(obs.map((o) => o.session_id));
    const files = new Set<string>();
    obs.forEach((o) => { o.files_read.forEach((f) => files.add(f)); o.files_modified.forEach((f) => files.add(f)); });
    let range: string | null = null;
    if (obs.length) {
      const fmt = (e: number) => new Date(e * 1000).toLocaleDateString([], { month: 'short', day: 'numeric' });
      const min = obs.reduce((m, o) => Math.min(m, o.at), Infinity);
      const max = obs.reduce((m, o) => Math.max(m, o.at), -Infinity);
      range = fmt(min) === fmt(max) ? fmt(max) : `${fmt(min)} – ${fmt(max)}`;
    }
    return { mem: obs.length, sessions: sess.size, files: files.size, range };
  }, [data, filters.project]);

  const ctxGroup = React.useMemo(() => {
    if (!ctxSessionId) return null;
    for (const d of days) {
      const g = d.sessions.find((x) => String(x.session.id) === ctxSessionId);
      if (g) return g;
    }
    return null;
  }, [ctxSessionId, days]);

  // default open state: most recent day + its most recent session
  const effOpenDays = React.useMemo(() => {
    if (openDays) return openDays;
    return days.length ? { [days[0].key]: true } : {};
  }, [openDays, days]);
  const effOpenSessions = React.useMemo(() => {
    if (openSessions) return openSessions;
    return days.length && days[0].sessions.length ? { [days[0].sessions[0].session.id]: true } : {};
  }, [openSessions, days]);

  const filterSig = filters.types.join(',') + '|' + filters.concepts.join(',') + '|' + (filters.file || '');
  const filterActive = filters.types.length > 0 || filters.concepts.length > 0 || !!filters.file;

  // when a narrowing filter engages, open everything that survived it
  React.useEffect(() => {
    if (!filterActive) return;
    const d: Record<string, boolean> = {};
    const s: Record<string, boolean> = {};
    days.forEach((day) => {
      d[day.key] = true;
      day.sessions.forEach((g) => { s[g.session.id] = true; });
    });
    setOpenDays(d);
    setOpenSessions(s);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [filterSig]);

  // scroll-spy: date rail + docked context header.
  React.useEffect(() => {
    const spy = () => {
      const sections = document.querySelectorAll('.day-group');
      let cur: string | null = null;
      sections.forEach((el) => {
        if (el.getBoundingClientRect().top <= 200) cur = el.id.replace('day-', '');
      });
      if (!cur && sections.length) cur = sections[0].id.replace('day-', '');
      setActiveDayKey(cur);

      const cards = document.querySelectorAll('.session-card');
      let sess: string | null = null;
      cards.forEach((el) => {
        const r = el.getBoundingClientRect();
        if (r.top <= 168 && r.bottom > 120) sess = el.id.replace('sess-', '');
      });
      setCtxSessionId(sess);
    };
    spy();
    window.addEventListener('scroll', spy, { passive: true });
    if (document.fonts && document.fonts.ready) document.fonts.ready.then(spy);
    let ro: ResizeObserver | null = null;
    if (typeof ResizeObserver !== 'undefined') {
      ro = new ResizeObserver(spy);
      ro.observe(document.body);
    }
    return () => { window.removeEventListener('scroll', spy); if (ro) ro.disconnect(); };
  }, [days]);

  const setAll = (open: boolean) => {
    const d: Record<string, boolean> = {};
    const s: Record<string, boolean> = {};
    days.forEach((day) => {
      d[day.key] = open;
      day.sessions.forEach((g) => { s[g.session.id] = open; });
    });
    setOpenDays(d);
    setOpenSessions(s);
    if (!open) setOpenObs({});
  };

  const toggleDay = (k: string) => setOpenDays({ ...effOpenDays, [k]: !effOpenDays[k] });
  const toggleSession = (k: string) => setOpenSessions({ ...effOpenSessions, [k]: !effOpenSessions[k] });
  const toggleObs = (id: number | string) => setOpenObs((p) => ({ ...p, [id]: !p[id] }));

  const jumpToDay = React.useCallback((key: string) => {
    setOpenDays((prev) => ({ ...(prev || effOpenDays), [key]: true }));
    setActiveDayKey(key);
    setTimeout(() => {
      const el = document.getElementById(`day-${key}`);
      if (el) {
        const top = el.getBoundingClientRect().top + window.scrollY - 132;
        window.scrollTo({ top, behavior: 'smooth' });
      }
    }, 60);
  }, [effOpenDays]);

  const jumpTo = React.useCallback((obsId: number | string) => {
    const o = data.observations.find((x) => x.id === obsId);
    if (!o) return;
    setFilters({ project: '', types: [], concepts: [], file: null });
    setOpenDays((prev) => ({ ...(prev || effOpenDays), [fmtDayKey(o.at)]: true }));
    setOpenSessions((prev) => ({ ...(prev || effOpenSessions), [o.session_id]: true }));
    setOpenObs((p) => ({ ...p, [obsId]: true }));
    setDrawer(null);
    setPanel(null);
    setFlashId(obsId);
    setTimeout(() => {
      const el = document.getElementById(`obs-${obsId}`);
      if (el) {
        const top = el.getBoundingClientRect().top + window.scrollY - 170;
        window.scrollTo({ top, behavior: 'smooth' });
      }
    }, 80);
    setTimeout(() => setFlashId(null), 2400);
  }, [data, effOpenDays, effOpenSessions]);

  const handleAsk = (query: string) => { agent.ask(query); };

  const openAgentAnswer = (id: string) => {
    setDrawer({ type: 'agent', id });
    setTimeout(() => agent.markViewed(id), 4000);
  };

  const openNote = (id: string) => { setPanel(null); setDrawer({ type: 'note', id }); };

  const handleSaveNote = (session: AgentSession) => {
    if (!session.answer) return;
    const note = {
      title: session.query,
      cited: session.answer.cited,
      blocks: session.answer.blocks,
    };
    saveNote(note);
    setSavedMap((m) => ({ ...m, [session.id]: true }));
  };

  // when an observation arrives over the live stream, reveal + flash it
  React.useEffect(() => {
    if (!live.lastStreamObs) return undefined;
    const o = data.observations.find((x) => x.id === live.lastStreamObs!.id);
    if (!o) return undefined;
    setOpenDays((prev) => ({ ...(prev || effOpenDays), [fmtDayKey(o.at)]: true }));
    setOpenSessions((prev) => ({ ...(prev || effOpenSessions), [o.session_id]: true }));
    setFlashId(o.id);
    const timer = setTimeout(() => setFlashId(null), 2400);
    return () => clearTimeout(timer);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [live.lastStreamObs && live.lastStreamObs.seq]);

  React.useEffect(() => {
    const onKey = (e: KeyboardEvent) => {
      if (e.key === 'Escape') { setPanel(null); setDrawer(null); }
    };
    document.addEventListener('keydown', onKey);
    return () => document.removeEventListener('keydown', onKey);
  }, []);

  const sessionsView = agent.sessions.map((s) => ({ ...s, saved: !!savedMap[s.id] }));
  const shownCount = days.reduce((n, d) => n + d.sessions.reduce((m, g) => m + g.observations.length, 0), 0);

  const appStyle = {
    '--accent': accent.a,
    '--accent-deep': accent.deep,
    '--accent-soft': dark ? hexA(accent.a, 0.22) : accent.soft,
    '--accent-tint': dark ? hexA(accent.a, 0.12) : accent.tint,
    '--rs': t.roundness,
  } as React.CSSProperties;

  return (
    <div className="app" data-density={t.density} data-panel={panel || undefined} style={appStyle}>
      <div className="page">
        <header className="topbar" data-screen-label="Header">
          <div className="brand">
            <button
              className="side-toggle"
              onClick={() => setPanel('files')}
              title="Files"
              aria-label="Open files"
              aria-expanded={panel === 'files'}
            >
              <Icon name="panelLeft" size={16} />
            </button>
            {/* eslint-disable-next-line @next/next/no-img-element */}
            <img src={LOGO} alt="cmem" className="brand-mark" />
            <span className="brand-word">cmem <em>cloud</em></span>
          </div>
          <SearchBar
            data={data}
            onAsk={handleAsk}
            onJump={jumpTo}
            onFile={(f) => setFilters((fl) => ({ ...fl, file: f }))}
            onConcept={(c) => setFilters((fl) => ({ ...fl, concepts: fl.concepts.includes(c) ? fl.concepts : [...fl.concepts, c] }))}
          />
          <div className="top-right">
            <button
              className="notes-toggle"
              onClick={() => setPanel('notes')}
              title="Notes"
              aria-label="Open notes"
              aria-expanded={panel === 'notes'}
            >
              <Icon name="stickyNote" size={15} />
              <span className="nt-label">Notes</span>
              <span className="nt-count">{notes.length}</span>
            </button>
            {onConnect && (
              <button
                className="notes-toggle"
                onClick={onConnect}
                title="Connect claude-mem"
                aria-label="Connect claude-mem"
              >
                <Icon name="database" size={15} />
                <span className="nt-label">Connect</span>
              </button>
            )}
            {onDevices && (
              <button
                className="notes-toggle"
                onClick={onDevices}
                title="Synced devices"
                aria-label="Open devices panel"
              >
                <Icon name="monitor" size={15} />
                <span className="nt-label">Devices</span>
              </button>
            )}
            <ThemeToggle theme={theme} setTheme={setTheme} />
            <SettingsMenu t={t} setTweak={setTweak} live={live} />
            <div className="project-select-wrap">
              <Icon name="folder" size={14} className="project-glyph" />
              <select
                className="project-select"
                value={filters.project}
                onChange={(e) => setFilters((f) => ({ ...f, project: e.target.value }))}
                aria-label="Filter by project"
              >
                <option value="">All projects</option>
                {projects.map((p) => <option key={p} value={p}>{p}</option>)}
              </select>
              <Icon name="chevronDown" size={13} className="project-caret" />
            </div>
          </div>
        </header>

        <ChipsBar data={data} filters={filters} setFilters={setFilters} />

        <div className="layout">
          <DateRail days={days} activeKey={activeDayKey} onJump={jumpToDay} />

          <main className="main" data-screen-label="Timeline">

            <PinnedRail notes={notes} onOpen={openNote} onTogglePin={togglePin} />

            <div className="context-bar">
              <div className="context-swap" key={ctxGroup ? ctxGroup.session.id : 'project'}>
                {ctxGroup ? (
                  <div className="project-head">
                    <h1 className="project-title ctx-prompt">{ctxGroup.session.request}</h1>
                    <p className="project-sub">
                      <span className={`project-dot p-${ctxGroup.session.project}`}></span> {ctxGroup.session.project}
                      <span className="dot-sep"> · </span>{fmtTime(ctxGroup.session.started)}–{fmtTime(ctxGroup.session.ended)}
                      <span className="dot-sep"> · </span>{ctxGroup.observations.length} {ctxGroup.observations.length === 1 ? 'memory' : 'memories'}
                    </p>
                  </div>
                ) : (
                  <div className="project-head">
                    <h1 className="project-title">{filters.project || 'All projects'}</h1>
                    <p className="project-sub">
                      {projStats.sessions} {projStats.sessions === 1 ? 'session' : 'sessions'}
                      <span className="dot-sep"> · </span>{projStats.mem.toLocaleString()} memories
                      <span className="dot-sep"> · </span>{projStats.files} files
                      {projStats.range && <><span className="dot-sep"> · </span>{projStats.range}</>}
                    </p>
                  </div>
                )}
              </div>
              <div className="toolbar-actions">
                <button className="tool-btn" onClick={() => setAll(true)}><Icon name="chevronsUpDown" size={14} /> Expand all</button>
                <button className="tool-btn" onClick={() => setAll(false)}><Icon name="chevronsDownUp" size={14} /> Collapse all</button>
              </div>
            </div>

            {filterActive && (
              <div className="filter-banner">
                <Icon name="search" size={14} />
                <span>
                  <strong>{shownCount}</strong> {shownCount === 1 ? 'memory' : 'memories'}
                  {filters.file && <> touching <code className="mono-inline">{filters.file}</code></>}
                  {filters.concepts.length > 0 && <> tagged <strong>{filters.concepts.join(', ')}</strong></>}
                  {filters.types.length > 0 && <> · {filters.types.join(' / ')}</>}
                </span>
                <button className="banner-clear" onClick={() => setFilters((f) => ({ ...f, types: [], concepts: [], file: null }))}>
                  <Icon name="x" size={12} /> Clear
                </button>
              </div>
            )}

            <Timeline
              days={days}
              openDays={effOpenDays} onToggleDay={toggleDay}
              openSessions={effOpenSessions} onToggleSession={toggleSession}
              openObs={openObs} onToggleObs={toggleObs}
              activeConcepts={filters.concepts}
              onConceptClick={(c) => setFilters((fl) => ({ ...fl, concepts: fl.concepts.includes(c) ? fl.concepts.filter((x) => x !== c) : [...fl.concepts, c] }))}
              onFileClick={(f) => setFilters((fl) => ({ ...fl, file: fl.file === f ? null : f }))}
              flashId={flashId}
              loading={live.status === 'connecting'}
            />
          </main>
        </div>
      </div>{/* /.page */}

      <div className="push-scrim" onClick={() => setPanel(null)}></div>

      <FilesPanel
        data={data} filters={filters} setFilters={setFilters} live={live}
        active={panel === 'files'} onClose={() => setPanel(null)}
      />
      <NotesPanel
        notes={notes} active={panel === 'notes'} onClose={() => setPanel(null)}
        onOpen={openNote} onTogglePin={togglePin} onDelete={deleteNote}
      />

      <AgentToasts sessions={sessionsView} onOpen={openAgentAnswer} onDismiss={agent.dismiss} />

      <AnswerDrawer
        drawer={drawer}
        agentSessions={sessionsView}
        notes={notes}
        citedObs={citedObs as Record<string, ViewerData['observations'][number]>}
        onClose={() => setDrawer(null)}
        onSaveNote={handleSaveNote}
        onDeleteNote={(id) => { deleteNote(id); setDrawer(null); }}
        onTogglePin={togglePin}
        onCite={jumpTo}
      />
    </div>
  );
}

