1	'use client';
2	
3	// ============================================================
4	// cmem cloud viewer — live cloud data source.
5	// Composes the app's real plumbing: paginated /api/{observations,
6	// summaries,prompts} for history + useSSE() for live rows +
7	// useStats() for totals, then normalizes cloud rows into the
8	// viewer's { sessions, prompts, observations } shape.
9	//
10	// Cloud field-name conventions (both paths handled):
11	//   pagination  → memory_session_id, content_session_id, arrays parsed
12	//   SSE (/stream)→ sdk_session_id | session_id | claude_session_id
13	// The canonical join key across all three is memory_session_id;
14	// the normalizers fall back through every alias the API can emit.
15	// (adapted from cmem-viewer-pro/cmem-viewer/live-data.js)
16	// ============================================================
17	import { useState, useEffect, useCallback, useMemo, useRef } from 'react';
18	import { useSSE, useStats } from '@/hooks';
19	import { API_ENDPOINTS } from '@/constants';
20	import type {
21	  VObservation, VSummary, VPrompt, ViewerData, LiveState,
22	} from './types';
23	
24	const MAX_ROWS = 600; // initial-load cap per endpoint
25	const FETCH_TIMEOUT_MS = 8000;
26	
27	// Rows may store epochs in ms or seconds — normalize to seconds.
28	const toSec = (e: unknown): number => {
29	  const n = Number(e);
30	  if (!n || Number.isNaN(n)) return Math.floor(Date.now() / 1000);
31	  return n > 1e12 ? Math.floor(n / 1000) : Math.floor(n);
32	};
33	
34	// facts / concepts / files_* arrive as arrays (parsed) OR JSON strings OR csv.
35	const parseList = (v: unknown): string[] => {
36	  if (Array.isArray(v)) return v.filter(Boolean).map(String);
37	  if (v === null || v === undefined || v === '') return [];
38	  if (typeof v === 'string') {
39	    try {
40	      const p = JSON.parse(v);
41	      if (Array.isArray(p)) return p.filter(Boolean).map(String);
42	    } catch { /* not JSON — fall through */ }
43	    return v.split(',').map((s) => s.trim()).filter(Boolean);
44	  }
45	  return [];
46	};
47	
48	const truncate = (s: unknown, n: number): string => {
49	  if (!s) return '';
50	  const t = String(s).replace(/\s+/g, ' ').trim();
51	  return t.length > n ? `${t.slice(0, n - 1).trimEnd()}…` : t;
52	};
53	
54	/* eslint-disable @typescript-eslint/no-explicit-any */
55	export function normObservation(row: any): VObservation {
56	  const narrative = row.narrative || row.text || '';
57	  return {
58	    id: row.id,
59	    session_id: row.memory_session_id || row.sdk_session_id || row.session_id || 'unknown-session',
60	    project: row.project || 'unknown',
61	    type: row.type || 'feature',
62	    title: row.title || truncate(narrative, 80) || 'Untitled observation',
63	    subtitle: row.subtitle || '',
64	    narrative,
65	    facts: parseList(row.facts),
66	    concepts: parseList(row.concepts),
67	    files_read: parseList(row.files_read),
68	    files_modified: parseList(row.files_modified),
69	    at: toSec(row.created_at_epoch != null ? row.created_at_epoch : row.created_at),
70	  };
71	}
72	
73	export function normSummary(row: any): VSummary {
74	  return {
75	    session_id: row.memory_session_id || row.session_id || 'unknown-session',
76	    project: row.project || 'unknown',
77	    request: row.request || '',
78	    investigated: row.investigated || '',
79	    learned: row.learned || '',
80	    completed: row.completed || '',
81	    next_steps: row.next_steps || '',
82	    at: toSec(row.created_at_epoch),
83	  };
84	}
85	
86	export function normPrompt(row: any): VPrompt {
87	  return {
88	    id: `prompt-${row.id}`,
89	    session_id: row.memory_session_id || row.content_session_id || row.claude_session_id || row.session_id || 'unknown-session',
90	    project: row.project || 'unknown',
91	    text: row.prompt_text || row.text || '',
92	    n: row.prompt_number || 0,
93	    at: toSec(row.created_at_epoch),
94	  };
95	}
96	/* eslint-enable @typescript-eslint/no-explicit-any */
97	
98	// Build the viewer's { sessions, prompts, observations } from normalized rows.
99	// Sessions are synthesized for every session id seen in observations;
100	// summaries and the first prompt enrich them when present.
101	function buildData(raw: {
102	  observations: VObservation[];
103	  summaries: VSummary[];
104	  prompts: VPrompt[];
105	}): ViewerData {
106	  const { observations } = raw;
107	
108	  const sumBySession: Record<string, VSummary> = {};
109	  raw.summaries.forEach((s) => {
110	    const prev = sumBySession[s.session_id];
111	    if (!prev || s.at >= prev.at) sumBySession[s.session_id] = s;
112	  });
113	
114	  const promptBySession: Record<string, VPrompt> = {};
115	  raw.prompts.forEach((p) => {
116	    if (!p.text) return;
117	    const prev = promptBySession[p.session_id];
118	    const pn = p.n || Infinity;
119	    const prevN = prev ? prev.n || Infinity : Infinity;
120	    // earliest prompt number wins; epoch only breaks ties
121	    if (!prev || pn < prevN || (pn === prevN && p.at < prev.at)) {
122	      promptBySession[p.session_id] = p;
123	    }
124	  });
125	
126	  const obsBySession: Record<string, VObservation[]> = {};
127	  observations.forEach((o) => {
128	    (obsBySession[o.session_id] = obsBySession[o.session_id] || []).push(o);
129	  });
130	
131	  const sessions = Object.keys(obsBySession).map((sid) => {
132	    const list = obsBySession[sid];
133	    let started = Infinity;
134	    let ended = -Infinity;
135	    list.forEach((o) => {
136	      if (o.at < started) started = o.at;
137	      if (o.at > ended) ended = o.at;
138	    });
139	    const sum = sumBySession[sid];
140	    const pr = promptBySession[sid];
141	    return {
142	      id: sid,
143	      project: (sum && sum.project) || list[0].project,
144	      started: started === Infinity ? toSec(null) : started,
145	      ended: ended === -Infinity ? toSec(null) : ended,
146	      request: (sum && sum.request) || (pr && truncate(pr.text, 110)) || list[0].title,
147	      learned: (sum && sum.learned) || '',
148	      completed: (sum && sum.completed) || '',
149	      next_steps: (sum && sum.next_steps) || '',
150	      hasSummary: !!sum,
151	    };
152	  });
153	
154	  return {
155	    sessions,
156	    prompts: Object.values(promptBySession).map((p) => ({ ...p, text: truncate(p.text, 400) })),
157	    observations,
158	    seedNotes: [],
159	  };
160	}
161	
162	const EMPTY_DATA: ViewerData = { sessions: [], prompts: [], observations: [], seedNotes: [] };
163	
164	// ---------- paginated history fetch (same-origin, cookie-authed) ----------
165	async function fetchJSON(path: string): Promise<unknown> {
166	  const ctrl = new AbortController();
167	  const timer = setTimeout(() => ctrl.abort(), FETCH_TIMEOUT_MS);
168	  try {
169	    const res = await fetch(path, { signal: ctrl.signal });
170	    if (!res.ok) throw new Error(`${path} → HTTP ${res.status}`);
171	    return await res.json();
172	  } finally {
173	    clearTimeout(timer);
174	  }
175	}
176	
177	async function fetchRows(endpoint: string): Promise<unknown[]> {
178	  const j = await fetchJSON(`${endpoint}?offset=0&limit=${MAX_ROWS}`);
179	  const items = Array.isArray(j) ? j : ((j as { items?: unknown[] })?.items || []);
180	  return items.slice(0, MAX_ROWS);
181	}
182	
183	const dedupeById = <T extends { id: number | string }>(list: T[]): T[] => {
184	  const seen = new Set<number | string>();
185	  return list.filter((x) => {
186	    if (seen.has(x.id)) return false;
187	    seen.add(x.id);
188	    return true;
189	  });
190	};
191	
192	interface RawNormalized {
193	  observations: VObservation[];
194	  summaries: VSummary[];
195	  prompts: VPrompt[];
196	}
197	
198	/**
199	 * useCloudData — the viewer's live data source.
200	 * status: 'connecting' → 'live' (history loaded) | 'offline' (load failed).
201	 * While mounted it also folds in live SSE rows from useSSE().
202	 */
203	export function useCloudData(): LiveState {
204	  const [base, setBase] = useState<RawNormalized | null>(null);
205	  const [status, setStatus] = useState<'connecting' | 'live' | 'offline'>('connecting');
206	  const [error, setError] = useState<string | null>(null);
207	
208	  const sse = useSSE();
209	  const { stats } = useStats();
210	
211	  const load = useCallback(async () => {
212	    setStatus('connecting');
213	    setError(null);
214	    // Summaries/prompts only enrich the timeline — a failure there shouldn't
215	    // throw away the observations (or vice versa isn't true: no obs, no viewer).
216	    const [obs, sums, prompts] = await Promise.allSettled([
217	      fetchRows(API_ENDPOINTS.OBSERVATIONS),
218	      fetchRows(API_ENDPOINTS.SUMMARIES),
219	      fetchRows(API_ENDPOINTS.PROMPTS),
220	    ]);
221	    if (obs.status === 'rejected') {
222	      setError(String((obs.reason as Error)?.message || obs.reason));
223	      setStatus('offline');
224	      return;
225	    }
226	    setBase({
227	      observations: dedupeById(obs.value.map(normObservation)),
228	      summaries: sums.status === 'fulfilled' ? sums.value.map(normSummary) : [],
229	      prompts: prompts.status === 'fulfilled' ? dedupeById(prompts.value.map(normPrompt)) : [],
230	    });
231	    setStatus('live');
232	  }, []);
233	
234	  // Kick off the one-time history load on mount.
235	  // eslint-disable-next-line react-hooks/set-state-in-effect
236	  useEffect(() => { load(); }, [load]);
237	
238	  // Fold live SSE rows over the loaded history (live rows win on id collision).
239	  const merged = useMemo<RawNormalized>(() => {
240	    const b = base || { observations: [], summaries: [], prompts: [] };
241	    const observations = dedupeById([...sse.observations.map(normObservation), ...b.observations]);
242	    const summaries = [...sse.summaries.map(normSummary), ...b.summaries];
243	    const prompts = dedupeById([...sse.prompts.map(normPrompt), ...b.prompts]);
244	    return { observations, summaries, prompts };
245	  }, [base, sse.observations, sse.summaries, sse.prompts]);
246	
247	  const data = useMemo(() => (base ? buildData(merged) : EMPTY_DATA), [base, merged]);
248	
249	  // Track the newest live observation so the UI can flash it in.
250	  const seqRef = useRef(0);
251	  const lastIdRef = useRef<number | string | null>(null);
252	  const [lastStreamObs, setLastStreamObs] = useState<LiveState['lastStreamObs']>(null);
253	  useEffect(() => {
254	    const top = sse.observations[0];
255	    if (!top || top.id === lastIdRef.current) return;
256	    lastIdRef.current = top.id;
257	    seqRef.current += 1;
258	    // Syncing an external system (the SSE stream) into local state — the
259	    // intended use of an effect; the newest live row drives the flash-in.
260	    setLastStreamObs({ id: top.id, seq: seqRef.current });
261	  }, [sse.observations]);
262	
263	  const isLive = status === 'live' && !!base;
264	  // Cloud /api/stats returns { observationCount, ... } (flat); the shared Stats
265	  // type only models the local-worker shape, so read the cloud field via cast.
266	  const obsCount = (stats as { observationCount?: number }).observationCount;
267	  const total = typeof obsCount === 'number' ? obsCount : null;
268	
269	  return {
270	    data,
271	    isLive,
272	    status,
273	    error,
274	    streamOk: sse.isConnected,
275	    proc: { isProcessing: sse.isProcessing, queueDepth: 0 },
276	    total,
277	    streamProjects: sse.projects || [],
278	    lastStreamObs,
279	    retry: load,
280	  };
281	}
282

