'use client';

// ============================================================
// cmem cloud viewer — live cloud data source.
// Composes the app's real plumbing: paginated /api/{observations,
// summaries,prompts} for history + useSSE() for live rows +
// useStats() for totals, then normalizes cloud rows into the
// viewer's { sessions, prompts, observations } shape.
//
// Cloud field-name conventions (both paths handled):
//   pagination  → memory_session_id, content_session_id, arrays parsed
//   SSE (/stream)→ sdk_session_id | session_id | claude_session_id
// The canonical join key across all three is memory_session_id;
// the normalizers fall back through every alias the API can emit.
// (adapted from cmem-viewer-pro/cmem-viewer/live-data.js)
// ============================================================
import { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { useSSE, useStats } from '@/hooks';
import { API_ENDPOINTS } from '@/constants';
import type {
  VObservation, VSummary, VPrompt, ViewerData, LiveState,
} from './types';

const MAX_ROWS = 600; // initial-load cap per endpoint
const FETCH_TIMEOUT_MS = 8000;

// Rows may store epochs in ms or seconds — normalize to seconds.
const toSec = (e: unknown): number => {
  const n = Number(e);
  if (!n || Number.isNaN(n)) return Math.floor(Date.now() / 1000);
  return n > 1e12 ? Math.floor(n / 1000) : Math.floor(n);
};

// facts / concepts / files_* arrive as arrays (parsed) OR JSON strings OR csv.
const parseList = (v: unknown): string[] => {
  if (Array.isArray(v)) return v.filter(Boolean).map(String);
  if (v === null || v === undefined || v === '') return [];
  if (typeof v === 'string') {
    try {
      const p = JSON.parse(v);
      if (Array.isArray(p)) return p.filter(Boolean).map(String);
    } catch { /* not JSON — fall through */ }
    return v.split(',').map((s) => s.trim()).filter(Boolean);
  }
  return [];
};

const truncate = (s: unknown, n: number): string => {
  if (!s) return '';
  const t = String(s).replace(/\s+/g, ' ').trim();
  return t.length > n ? `${t.slice(0, n - 1).trimEnd()}…` : t;
};

/* eslint-disable @typescript-eslint/no-explicit-any */
export function normObservation(row: any): VObservation {
  const narrative = row.narrative || row.text || '';
  return {
    id: row.id,
    session_id: row.memory_session_id || row.sdk_session_id || row.session_id || 'unknown-session',
    project: row.project || 'unknown',
    type: row.type || 'feature',
    title: row.title || truncate(narrative, 80) || 'Untitled observation',
    subtitle: row.subtitle || '',
    narrative,
    facts: parseList(row.facts),
    concepts: parseList(row.concepts),
    files_read: parseList(row.files_read),
    files_modified: parseList(row.files_modified),
    at: toSec(row.created_at_epoch != null ? row.created_at_epoch : row.created_at),
  };
}

export function normSummary(row: any): VSummary {
  return {
    session_id: row.memory_session_id || row.session_id || 'unknown-session',
    project: row.project || 'unknown',
    request: row.request || '',
    investigated: row.investigated || '',
    learned: row.learned || '',
    completed: row.completed || '',
    next_steps: row.next_steps || '',
    at: toSec(row.created_at_epoch),
  };
}

export function normPrompt(row: any): VPrompt {
  return {
    id: `prompt-${row.id}`,
    session_id: row.memory_session_id || row.content_session_id || row.claude_session_id || row.session_id || 'unknown-session',
    project: row.project || 'unknown',
    text: row.prompt_text || row.text || '',
    n: row.prompt_number || 0,
    at: toSec(row.created_at_epoch),
  };
}
/* eslint-enable @typescript-eslint/no-explicit-any */

// Build the viewer's { sessions, prompts, observations } from normalized rows.
// Sessions are synthesized for every session id seen in observations;
// summaries and the first prompt enrich them when present.
function buildData(raw: {
  observations: VObservation[];
  summaries: VSummary[];
  prompts: VPrompt[];
}): ViewerData {
  const { observations } = raw;

  const sumBySession: Record<string, VSummary> = {};
  raw.summaries.forEach((s) => {
    const prev = sumBySession[s.session_id];
    if (!prev || s.at >= prev.at) sumBySession[s.session_id] = s;
  });

  const promptBySession: Record<string, VPrompt> = {};
  raw.prompts.forEach((p) => {
    if (!p.text) return;
    const prev = promptBySession[p.session_id];
    const pn = p.n || Infinity;
    const prevN = prev ? prev.n || Infinity : Infinity;
    // earliest prompt number wins; epoch only breaks ties
    if (!prev || pn < prevN || (pn === prevN && p.at < prev.at)) {
      promptBySession[p.session_id] = p;
    }
  });

  const obsBySession: Record<string, VObservation[]> = {};
  observations.forEach((o) => {
    (obsBySession[o.session_id] = obsBySession[o.session_id] || []).push(o);
  });

  const sessions = Object.keys(obsBySession).map((sid) => {
    const list = obsBySession[sid];
    let started = Infinity;
    let ended = -Infinity;
    list.forEach((o) => {
      if (o.at < started) started = o.at;
      if (o.at > ended) ended = o.at;
    });
    const sum = sumBySession[sid];
    const pr = promptBySession[sid];
    return {
      id: sid,
      project: (sum && sum.project) || list[0].project,
      started: started === Infinity ? toSec(null) : started,
      ended: ended === -Infinity ? toSec(null) : ended,
      request: (sum && sum.request) || (pr && truncate(pr.text, 110)) || list[0].title,
      learned: (sum && sum.learned) || '',
      completed: (sum && sum.completed) || '',
      next_steps: (sum && sum.next_steps) || '',
      hasSummary: !!sum,
    };
  });

  return {
    sessions,
    prompts: Object.values(promptBySession).map((p) => ({ ...p, text: truncate(p.text, 400) })),
    observations,
    seedNotes: [],
  };
}

const EMPTY_DATA: ViewerData = { sessions: [], prompts: [], observations: [], seedNotes: [] };

// ---------- paginated history fetch (same-origin, cookie-authed) ----------
async function fetchJSON(path: string): Promise<unknown> {
  const ctrl = new AbortController();
  const timer = setTimeout(() => ctrl.abort(), FETCH_TIMEOUT_MS);
  try {
    const res = await fetch(path, { signal: ctrl.signal });
    if (!res.ok) throw new Error(`${path} → HTTP ${res.status}`);
    return await res.json();
  } finally {
    clearTimeout(timer);
  }
}

async function fetchRows(endpoint: string): Promise<unknown[]> {
  const j = await fetchJSON(`${endpoint}?offset=0&limit=${MAX_ROWS}`);
  const items = Array.isArray(j) ? j : ((j as { items?: unknown[] })?.items || []);
  return items.slice(0, MAX_ROWS);
}

const dedupeById = <T extends { id: number | string }>(list: T[]): T[] => {
  const seen = new Set<number | string>();
  return list.filter((x) => {
    if (seen.has(x.id)) return false;
    seen.add(x.id);
    return true;
  });
};

interface RawNormalized {
  observations: VObservation[];
  summaries: VSummary[];
  prompts: VPrompt[];
}

/**
 * useCloudData — the viewer's live data source.
 * status: 'connecting' → 'live' (history loaded) | 'offline' (load failed).
 * While mounted it also folds in live SSE rows from useSSE().
 */
export function useCloudData(): LiveState {
  const [base, setBase] = useState<RawNormalized | null>(null);
  const [status, setStatus] = useState<'connecting' | 'live' | 'offline'>('connecting');
  const [error, setError] = useState<string | null>(null);

  const sse = useSSE();
  const { stats } = useStats();

  const load = useCallback(async () => {
    setStatus('connecting');
    setError(null);
    // Summaries/prompts only enrich the timeline — a failure there shouldn't
    // throw away the observations (or vice versa isn't true: no obs, no viewer).
    const [obs, sums, prompts] = await Promise.allSettled([
      fetchRows(API_ENDPOINTS.OBSERVATIONS),
      fetchRows(API_ENDPOINTS.SUMMARIES),
      fetchRows(API_ENDPOINTS.PROMPTS),
    ]);
    if (obs.status === 'rejected') {
      setError(String((obs.reason as Error)?.message || obs.reason));
      setStatus('offline');
      return;
    }
    setBase({
      observations: dedupeById(obs.value.map(normObservation)),
      summaries: sums.status === 'fulfilled' ? sums.value.map(normSummary) : [],
      prompts: prompts.status === 'fulfilled' ? dedupeById(prompts.value.map(normPrompt)) : [],
    });
    setStatus('live');
  }, []);

  // Kick off the one-time history load on mount.
  // eslint-disable-next-line react-hooks/set-state-in-effect
  useEffect(() => { load(); }, [load]);

  // Fold live SSE rows over the loaded history (live rows win on id collision).
  const merged = useMemo<RawNormalized>(() => {
    const b = base || { observations: [], summaries: [], prompts: [] };
    const observations = dedupeById([...sse.observations.map(normObservation), ...b.observations]);
    const summaries = [...sse.summaries.map(normSummary), ...b.summaries];
    const prompts = dedupeById([...sse.prompts.map(normPrompt), ...b.prompts]);
    return { observations, summaries, prompts };
  }, [base, sse.observations, sse.summaries, sse.prompts]);

  const data = useMemo(() => (base ? buildData(merged) : EMPTY_DATA), [base, merged]);

  // Track the newest live observation so the UI can flash it in.
  const seqRef = useRef(0);
  const lastIdRef = useRef<number | string | null>(null);
  const [lastStreamObs, setLastStreamObs] = useState<LiveState['lastStreamObs']>(null);
  useEffect(() => {
    const top = sse.observations[0];
    if (!top || top.id === lastIdRef.current) return;
    lastIdRef.current = top.id;
    seqRef.current += 1;
    // Syncing an external system (the SSE stream) into local state — the
    // intended use of an effect; the newest live row drives the flash-in.
    setLastStreamObs({ id: top.id, seq: seqRef.current });
  }, [sse.observations]);

  const isLive = status === 'live' && !!base;
  // Cloud /api/stats returns { observationCount, ... } (flat); the shared Stats
  // type only models the local-worker shape, so read the cloud field via cast.
  const obsCount = (stats as { observationCount?: number }).observationCount;
  const total = typeof obsCount === 'number' ? obsCount : null;

  return {
    data,
    isLive,
    status,
    error,
    streamOk: sse.isConnected,
    proc: { isProcessing: sse.isProcessing, queueDepth: 0 },
    total,
    streamProjects: sse.projects || [],
    lastStreamObs,
    retry: load,
  };
}

