'use client';

import { useState, useEffect, useRef, Suspense } from 'react';
import { useSearchParams } from 'next/navigation';
import { Paywall } from '@/components/dashboard/Paywall';
import { ConnectModal } from '@/components/dashboard/ConnectModal';
import { DevicesPanel } from '@/components/dashboard/DevicesPanel';
import { CloudViewer } from '@/components/cloud-viewer';
import { usePro } from '@/hooks';
import { useSession } from '@/lib/auth-client';

function DashboardContent() {
  const searchParams = useSearchParams();
  const { proStatus, startCheckout, refreshStatus, isLoading: isProLoading } = usePro();
  const { data: authData } = useSession();
  const user = authData?.user;

  const [checkoutProcessing, setCheckoutProcessing] = useState(false);
  const [connectOpen, setConnectOpen] = useState(false);
  const [devicesOpen, setDevicesOpen] = useState(false);
  const autoConnectedRef = useRef(false);
  const provisionRanRef = useRef(false);

  // Handle checkout success/cancel from Stripe redirect
  useEffect(() => {
    const checkout = searchParams.get('checkout');
    const sessionId = searchParams.get('session_id');

    // The effect re-fires when refreshStatus changes identity (session null → user)
    // while checkout=success is still in the URL; without the ref a second
    // concurrent POST races provisioning and can rotate the tokens the
    // ConnectModal is already displaying.
    if (checkout === 'success' && !provisionRanRef.current) {
      provisionRanRef.current = true;
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setCheckoutProcessing(true);

      if (!sessionId) {
        refreshStatus();
        setCheckoutProcessing(false);
        setConnectOpen(true);
        autoConnectedRef.current = true;
        window.history.replaceState({}, '', '/dashboard');
        return;
      }

      // Try to provision via fallback endpoint (in case the webhook didn't fire)
      fetch('/api/pro/provision', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ sessionId }),
      })
        .then(() => refreshStatus())
        .catch((err) => {
          console.error('Provision failed, trying status refresh:', err);
          refreshStatus();
        })
        .finally(() => {
          setCheckoutProcessing(false);
          // Surface the connect/setup instructions right away
          setConnectOpen(true);
          autoConnectedRef.current = true;
          window.history.replaceState({}, '', '/dashboard');
        });
    } else if (checkout === 'cancelled') {
      window.history.replaceState({}, '', '/dashboard');
    }
  }, [searchParams, refreshStatus]);

  // First-run onboarding: a Pro user who hasn't finished setup gets the connect
  // instructions opened once automatically.
  useEffect(() => {
    if (autoConnectedRef.current) return;
    if (proStatus?.isPro && !proStatus?.setupCompleted) {
      autoConnectedRef.current = true;
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setConnectOpen(true);
    }
  }, [proStatus?.isPro, proStatus?.setupCompleted]);

  // Decide paywall-vs-viewer only once Pro status is known (avoids gate flash).
  if (isProLoading || checkoutProcessing) {
    return (
      <div className="dashboard-loading">
        <div className="loading-spinner" />
        <p>{searchParams.get('checkout') === 'success' ? 'Setting up your Pro account…' : 'Loading…'}</p>
      </div>
    );
  }

  if (!proStatus?.isPro) {
    return (
      <Paywall
        proStatus={proStatus}
        onUpgrade={startCheckout}
        isLoading={isProLoading}
      />
    );
  }

  return (
    <>
      <CloudViewer key={user?.id || 'anon'} userId={user?.id} onConnect={() => setConnectOpen(true)} onDevices={() => setDevicesOpen(true)} />
      <ConnectModal open={connectOpen} onClose={() => setConnectOpen(false)} />
      <DevicesPanel open={devicesOpen} onClose={() => setDevicesOpen(false)} />
    </>
  );
}

export default function DashboardPage() {
  return (
    <Suspense fallback={<div className="dashboard-loading">Loading dashboard...</div>}>
      <DashboardContent />
    </Suspense>
  );
}

