1	'use client';
2	
3	// ============================================================
4	// cmem cloud viewer — search, "Ask Your Agent" background sessions, Notes
5	// The agent answer is synthesized client-side from the loaded memories
6	// (an instant local recall + compose over the user's own observations).
7	// (ported from cmem-viewer-pro/cmem-viewer/search-agent.jsx)
8	// ============================================================
9	import * as React from 'react';
10	import { Icon, TYPE_META, fmtDayLabel, baseName, dirName } from './format';
11	import type { ViewerData, VObservation, Note, NoteBlock } from './types';
12	
13	const LOGO = '/cmem-viewer-logo.jpg';
14	
15	export interface AgentAnswer { cited: (number | string)[]; blocks: NoteBlock[] }
16	export interface AgentSession {
17	  id: string;
18	  query: string;
19	  status: 'running' | 'done';
20	  stage: string;
21	  answer: AgentAnswer | null;
22	  viewed: boolean;
23	  saved?: boolean;
24	}
25	
26	const STOPWORDS = new Set(['the', 'a', 'an', 'and', 'or', 'for', 'with', 'how', 'what', 'why', 'does', 'did', 'is', 'are', 'was', 'were', 'do', 'we', 'our', 'you', 'your', 'when', 'where', 'that', 'this', 'about', 'work', 'works']);
27	
28	function tokenize(q: string): string[] {
29	  return q.toLowerCase().split(/[^a-z0-9-]+/).filter((t) => t.length > 2 && !STOPWORDS.has(t));
30	}
31	
32	function scoreText(tokens: string[], text: string, weight: number): number {
33	  if (!text) return 0;
34	  const lower = text.toLowerCase();
35	  let s = 0;
36	  tokens.forEach((t) => { if (lower.includes(t)) s += weight; });
37	  return s;
38	}
39	
40	function scoreObservation(tokens: string[], o: VObservation): number {
41	  return scoreText(tokens, o.title, 3)
42	    + scoreText(tokens, (o.concepts || []).join(' '), 3)
43	    + scoreText(tokens, o.subtitle, 2)
44	    + scoreText(tokens, (o.facts || []).join(' '), 2)
45	    + scoreText(tokens, o.narrative, 1)
46	    + scoreText(tokens, (o.files_read || []).concat(o.files_modified || []).join(' '), 2);
47	}
48	
49	export interface SearchResult {
50	  observations: VObservation[];
51	  files: [string, number][];
52	  concepts: string[];
53	}
54	
55	// Instant string-match search across the loaded memories
56	export function searchMemory(query: string, data: ViewerData): SearchResult {
57	  const tokens = tokenize(query);
58	  const raw = query.trim().toLowerCase();
59	  if (!raw) return { observations: [], files: [], concepts: [] };
60	
61	  const scored = data.observations
62	    .map((o) => ({ o, s: scoreObservation(tokens.length ? tokens : [raw], o) }))
63	    .filter((x) => x.s > 0)
64	    .sort((a, b) => b.s - a.s || b.o.at - a.o.at);
65	
66	  const fileSet = new Map<string, number>();
67	  data.observations.forEach((o) => {
68	    (o.files_read || []).concat(o.files_modified || []).forEach((f) => {
69	      if (f.toLowerCase().includes(raw) || tokens.some((t) => f.toLowerCase().includes(t))) {
70	        fileSet.set(f, (fileSet.get(f) || 0) + 1);
71	      }
72	    });
73	  });
74	
75	  const conceptSet = new Map<string, number>();
76	  data.observations.forEach((o) => {
77	    (o.concepts || []).forEach((c) => {
78	      if (c.includes(raw) || tokens.some((t) => c.includes(t))) {
79	        conceptSet.set(c, (conceptSet.get(c) || 0) + 1);
80	      }
81	    });
82	  });
83	
84	  return {
85	    observations: scored.slice(0, 5).map((x) => x.o),
86	    files: [...fileSet.entries()].sort((a, b) => b[1] - a[1]).slice(0, 4),
87	    concepts: [...conceptSet.entries()].sort((a, b) => b[1] - a[1]).slice(0, 6).map((e) => e[0]),
88	  };
89	}
90	
91	// ---------- Agent answer synthesis ----------
92	export function synthesizeAnswer(query: string, data: ViewerData): AgentAnswer {
93	  const tokens = tokenize(query);
94	  const scored = data.observations
95	    .map((o) => ({ o, s: scoreObservation(tokens, o) }))
96	    .filter((x) => x.s > 0)
97	    .sort((a, b) => b.s - a.s || b.o.at - a.o.at)
98	    .slice(0, 5);
99	
100	  if (scored.length === 0) {
101	    return {
102	      cited: [],
103	      blocks: [
104	        { kind: 'p', text: `I went through all ${data.observations.length.toLocaleString()} observations and nothing matches “${query}” yet. Either we haven’t worked on this, or it’s phrased differently in memory.` },
105	        { kind: 'p', text: 'Try a concept chip from the filter bar, or rephrase with a file name or identifier — exact symbols match best.' },
106	      ],
107	    };
108	  }
109	
110	  const top = scored.map((x) => x.o);
111	  const projects = [...new Set(top.map((o) => o.project))];
112	  const latest = top.reduce((a, b) => (a.at > b.at ? a : b));
113	  const latestDay = fmtDayLabel(latest.at);
114	  const sessionsById = Object.fromEntries(data.sessions.map((s) => [s.id, s]));
115	  const latestSession = sessionsById[latest.session_id];
116	
117	  const bullets: string[] = [];
118	  top.forEach((o) => {
119	    const best = (o.facts || [])
120	      .map((f) => ({ f, s: scoreText(tokens, f, 1) }))
121	      .sort((a, b) => b.s - a.s)[0];
122	    if (best) bullets.push(best.f);
123	  });
124	
125	  const blocks: NoteBlock[] = [
126	    { kind: 'p', text: `I found ${top.length} ${top.length === 1 ? 'memory' : 'memories'} about “${query}” across ${projects.join(' and ')} — most recently “${latest.title}” from ${latestDay.lead.toLowerCase() === 'today' || latestDay.lead.toLowerCase() === 'yesterday' ? latestDay.lead.toLowerCase() : latestDay.rest}.` },
127	    { kind: 'bullets', items: bullets.slice(0, 4) },
128	  ];
129	  if (latestSession && latestSession.next_steps) {
130	    blocks.push({ kind: 'p', text: `Open thread from that work: ${latestSession.next_steps}` });
131	  }
132	  blocks.push({ kind: 'cite', ids: top.map((o) => o.id) });
133	  return { cited: top.map((o) => o.id), blocks };
134	}
135	
136	// ---------- Background agent sessions ----------
137	export function useAgentSessions(data: ViewerData) {
138	  const [sessions, setSessions] = React.useState<AgentSession[]>([]);
139	  const idRef = React.useRef(0);
140	
141	  const ask = React.useCallback((query: string) => {
142	    const id = `agent-${++idRef.current}-${Date.now()}`;
143	    const matches = searchMemory(query, data).observations.length;
144	    setSessions((prev) => [...prev, { id, query, status: 'running', stage: 'Searching memory…', answer: null, viewed: false }]);
145	
146	    const stages: [number, string][] = [
147	      [900, `Reading ${Math.max(matches, 2)} observations…`],
148	      [2300, 'Composing answer…'],
149	    ];
150	    stages.forEach(([delay, stage]) => {
151	      setTimeout(() => {
152	        setSessions((prev) => prev.map((s) => (s.id === id && s.status === 'running' ? { ...s, stage } : s)));
153	      }, delay);
154	    });
155	    setTimeout(() => {
156	      const answer = synthesizeAnswer(query, data);
157	      setSessions((prev) => prev.map((s) => (s.id === id ? { ...s, status: 'done', stage: 'Answer ready', answer } : s)));
158	    }, 3600);
159	    return id;
160	  }, [data]);
161	
162	  const dismiss = React.useCallback((id: string) => {
163	    setSessions((prev) => prev.filter((s) => s.id !== id));
164	  }, []);
165	
166	  const markViewed = React.useCallback((id: string) => {
167	    setSessions((prev) => prev.map((s) => (s.id === id ? { ...s, viewed: true } : s)));
168	  }, []);
169	
170	  return { sessions, ask, dismiss, markViewed };
171	}
172	
173	// ---------- Notes (persisted) ----------
174	// Notes hold memory excerpts, so the key MUST be scoped per user — an unscoped
175	// key would show one account's saved answers to the next account on a shared browser.
176	const NOTES_KEY_BASE = 'cmem-viewer-notes-v2';
177	
178	export function useNotes(seedNotes: Note[], userId?: string | null) {
179	  const notesKey = userId ? `${NOTES_KEY_BASE}:${userId}` : NOTES_KEY_BASE;
180	  const [notes, setNotes] = React.useState<Note[]>(() => {
181	    try {
182	      const raw = localStorage.getItem(notesKey);
183	      if (raw) {
184	        const arr = JSON.parse(raw);
185	        if (Array.isArray(arr) && arr.length) return arr;
186	      }
187	    } catch { /* ignore */ }
188	    return seedNotes;
189	  });
190	
191	  React.useEffect(() => {
192	    try { localStorage.setItem(notesKey, JSON.stringify(notes)); } catch { /* ignore */ }
193	  }, [notes, notesKey]);
194	
195	  const saveNote = React.useCallback((note: Omit<Note, 'id' | 'created' | 'pinned'>) => {
196	    setNotes((prev) => [{ ...note, id: `note-${Date.now()}`, created: Math.floor(Date.now() / 1000), pinned: false }, ...prev]);
197	  }, []);
198	
199	  const deleteNote = React.useCallback((id: string) => {
200	    setNotes((prev) => prev.filter((n) => n.id !== id));
201	  }, []);
202	
203	  const togglePin = React.useCallback((id: string) => {
204	    setNotes((prev) => prev.map((n) => (n.id === id ? { ...n, pinned: !n.pinned } : n)));
205	  }, []);
206	
207	  return { notes, saveNote, deleteNote, togglePin };
208	}
209	
210	// ---------- Search bar with instant results ----------
211	export function SearchBar({ data, onAsk, onJump, onFile, onConcept }: {
212	  data: ViewerData;
213	  onAsk: (q: string) => void;
214	  onJump: (id: number | string) => void;
215	  onFile: (f: string) => void;
216	  onConcept: (c: string) => void;
217	}) {
218	  const [query, setQuery] = React.useState('');
219	  const [open, setOpen] = React.useState(false);
220	  const wrapRef = React.useRef<HTMLDivElement>(null);
221	  const inputRef = React.useRef<HTMLInputElement>(null);
222	
223	  const results = React.useMemo(() => searchMemory(query, data), [query, data]);
224	  const hasQuery = query.trim().length > 0;
225	
226	  React.useEffect(() => {
227	    const onDocClick = (e: MouseEvent) => {
228	      if (wrapRef.current && !wrapRef.current.contains(e.target as Node)) setOpen(false);
229	    };
230	    const onKey = (e: KeyboardEvent) => {
231	      const active = document.activeElement as HTMLElement | null;
232	      if (e.key === '/' && active !== inputRef.current
233	          && !['INPUT', 'TEXTAREA'].includes(active?.tagName || '')) {
234	        e.preventDefault();
235	        inputRef.current?.focus();
236	      }
237	    };
238	    document.addEventListener('mousedown', onDocClick);
239	    document.addEventListener('keydown', onKey);
240	    return () => {
241	      document.removeEventListener('mousedown', onDocClick);
242	      document.removeEventListener('keydown', onKey);
243	    };
244	  }, []);
245	
246	  const fireAsk = () => {
247	    if (!hasQuery) return;
248	    onAsk(query.trim());
249	    setQuery('');
250	    setOpen(false);
251	    inputRef.current?.blur();
252	  };
253	
254	  return (
255	    <div className="search-wrap" ref={wrapRef}>
256	      <div className={`search-pill${open && hasQuery ? ' engaged' : ''}`}>
257	        <Icon name="search" size={19} className="search-glyph" />
258	        <input
259	          ref={inputRef}
260	          type="text"
261	          value={query}
262	          placeholder="Search your memory…"
263	          onChange={(e) => { setQuery(e.target.value); setOpen(true); }}
264	          onFocus={() => setOpen(true)}
265	          onKeyDown={(e) => {
266	            if (e.key === 'Enter') fireAsk();
267	            if (e.key === 'Escape') { setOpen(false); (e.target as HTMLInputElement).blur(); }
268	          }}
269	        />
270	        {hasQuery
271	          ? <button className="search-clear" onClick={() => { setQuery(''); inputRef.current?.focus(); }} aria-label="Clear search"><Icon name="x" size={14} /></button>
272	          : <kbd className="search-kbd">/</kbd>}
273	      </div>
274	
275	      {open && hasQuery && (
276	        <div className="search-drop">
277	          <button className="ask-row" onClick={fireAsk}>
278	            <span className="ask-glyph"><Icon name="sparkles" size={16} /></span>
279	            <span className="ask-text">Ask your agent: <em>“{query.trim()}”</em></span>
280	            <span className="ask-hint">runs in background · ⏎</span>
281	          </button>
282	
283	          {results.observations.length > 0 && (
284	            <div className="drop-section">
285	              <p className="drop-label">Memories</p>
286	              {results.observations.map((o) => {
287	                const m = TYPE_META[o.type] || TYPE_META.feature;
288	                return (
289	                  <button key={o.id} className="drop-row" onClick={() => { onJump(o.id); setOpen(false); setQuery(''); }}>
290	                    <span className="obs-type-bubble sm" data-type={o.type} style={{ background: m.bg, color: m.fg }}><Icon name={m.icon} size={12} /></span>
291	                    <span className="drop-row-title">{o.title}</span>
292	                    <span className="drop-row-meta">{o.project} · {fmtDayLabel(o.at).lead}</span>
293	                  </button>
294	                );
295	              })}
296	            </div>
297	          )}
298	
299	          {results.files.length > 0 && (
300	            <div className="drop-section">
301	              <p className="drop-label">Files</p>
302	              {results.files.map(([f, n]) => (
303	                <button key={f} className="drop-row" onClick={() => { onFile(f); setOpen(false); setQuery(''); }}>
304	                  <span className="drop-file-glyph"><Icon name="fileCode" size={14} /></span>
305	                  <span className="drop-row-title mono">{baseName(f)}<span className="drop-dir">{dirName(f)}</span></span>
306	                  <span className="drop-row-meta">{n} {n === 1 ? 'memory' : 'memories'}</span>
307	                </button>
308	              ))}
309	            </div>
310	          )}
311	
312	          {results.concepts.length > 0 && (
313	            <div className="drop-section">
314	              <p className="drop-label">Concepts</p>
315	              <div className="drop-concepts">
316	                {results.concepts.map((c) => (
317	                  <button key={c} className="concept-chip" onClick={() => { onConcept(c); setOpen(false); setQuery(''); }}>{c}</button>
318	                ))}
319	              </div>
320	            </div>
321	          )}
322	
323	          {results.observations.length === 0 && results.files.length === 0 && results.concepts.length === 0 && (
324	            <p className="drop-empty">No instant matches — ask your agent instead.</p>
325	          )}
326	        </div>
327	      )}
328	    </div>
329	  );
330	}
331	
332	// ---------- Background-session toasts ----------
333	export function AgentToasts({ sessions, onOpen, onDismiss }: {
334	  sessions: AgentSession[];
335	  onOpen: (id: string) => void;
336	  onDismiss: (id: string) => void;
337	}) {
338	  const visible = sessions;
339	  if (visible.length === 0) return null;
340	  return (
341	    <div className="agent-toasts">
342	      {visible.map((s) => (
343	        <div key={s.id} className={`agent-toast${s.status === 'done' ? ' done' : ''}`}>
344	          {/* eslint-disable-next-line @next/next/no-img-element */}
345	          <img src={LOGO} alt="" className={`toast-mark${s.status === 'running' ? ' spin' : ''}`} />
346	          <button
347	            className="toast-main"
348	            onClick={() => s.status === 'done' && onOpen(s.id)}
349	            disabled={s.status !== 'done'}
350	          >
351	            <span className="toast-query">“{s.query}”</span>
352	            <span className={`toast-stage${s.status === 'done' && !s.viewed ? ' ready' : ''}`}>
353	              {s.status === 'done' ? (s.viewed ? 'Answer · tap to reopen' : 'Answer ready — tap to read') : s.stage}
354	            </span>
355	          </button>
356	          <button className="toast-x" onClick={() => onDismiss(s.id)} aria-label="Dismiss"><Icon name="x" size={13} /></button>
357	        </div>
358	      ))}
359	    </div>
360	  );
361	}
362	
363	// ---------- Streaming block renderer ----------
364	type RenderedBlock =
365	  | { kind: 'p'; text: string }
366	  | { kind: 'bullets'; items: string[] }
367	  | { kind: 'cite'; ids: (number | string)[] };
368	
369	// Word-budget "typing" clip, computed as a pure pass so no render-scope
370	// variable is mutated during render (compiler-safe).
371	function clipBlocks(blocks: NoteBlock[], shown: number): RenderedBlock[] {
372	  const out: RenderedBlock[] = [];
373	  let budget = shown;
374	  const clip = (text: string) => {
375	    const words = text.split(' ');
376	    if (budget >= words.length) { budget -= words.length; return text; }
377	    const o = words.slice(0, Math.max(0, budget)).join(' ');
378	    budget = 0;
379	    return o;
380	  };
381	  for (let i = 0; i < blocks.length; i++) {
382	    const b = blocks[i];
383	    if (budget <= 0 && shown !== Infinity && i > 0) break;
384	    if (b.kind === 'p') {
385	      const t = shown === Infinity ? (b.text || '') : clip(b.text || '');
386	      if (t) out.push({ kind: 'p', text: t });
387	    } else if (b.kind === 'bullets') {
388	      const items: string[] = [];
389	      for (const it of (b.items || [])) {
390	        const t = shown === Infinity ? it : clip(it);
391	        if (t) items.push(t);
392	        if (budget <= 0 && shown !== Infinity) break;
393	      }
394	      if (items.length) out.push({ kind: 'bullets', items });
395	    } else if (b.kind === 'cite' && (shown === Infinity || budget > 0)) {
396	      out.push({ kind: 'cite', ids: b.ids || [] });
397	    }
398	  }
399	  return out;
400	}
401	
402	function StreamedBlocks({ blocks, animate, citedObs, onCite }: {
403	  blocks: NoteBlock[];
404	  animate: boolean;
405	  citedObs: Record<string, VObservation>;
406	  onCite: (id: number | string) => void;
407	}) {
408	  const totalWords = React.useMemo(
409	    () => blocks.reduce((n, b) => n + (b.kind === 'p' ? (b.text || '').split(' ').length : b.kind === 'bullets' ? (b.items || []).join(' ').split(' ').length : 1), 0),
410	    [blocks],
411	  );
412	  const [shown, setShown] = React.useState(animate ? 0 : Infinity);
413	
414	  React.useEffect(() => {
415	    if (!animate) { setShown(Infinity); return undefined; }
416	    setShown(0);
417	    let count = 0;
418	    const iv = setInterval(() => {
419	      count += 3;
420	      setShown(count);
421	      if (count >= totalWords + 5) clearInterval(iv);
422	    }, 50);
423	    return () => clearInterval(iv);
424	  }, [animate, blocks, totalWords]);
425	
426	  const rendered = clipBlocks(blocks, shown);
427	
428	  return (
429	    <div className="answer-blocks">
430	      {rendered.map((b, i) => {
431	        if (b.kind === 'p') {
432	          return <p key={i} className="answer-p">{b.text}</p>;
433	        }
434	        if (b.kind === 'bullets') {
435	          return <ul key={i} className="answer-bullets">{b.items.map((it, j) => <li key={j}>{it}</li>)}</ul>;
436	        }
437	        return (
438	          <div key={i} className="answer-cites">
439	            <p className="drop-label">From memory</p>
440	            <div className="cite-chips">
441	              {b.ids.map((id) => {
442	                const o = citedObs[id];
443	                if (!o) return null;
444	                const m = TYPE_META[o.type] || TYPE_META.feature;
445	                return (
446	                  <button key={id} className="cite-chip" onClick={() => onCite(id)}>
447	                    <span className="obs-type-bubble sm" data-type={o.type} style={{ background: m.bg, color: m.fg }}><Icon name={m.icon} size={11} /></span>
448	                    <span>#{id} {o.title}</span>
449	                  </button>
450	                );
451	              })}
452	            </div>
453	          </div>
454	        );
455	      })}
456	    </div>
457	  );
458	}
459	
460	// ---------- Right drawer: agent answer or saved note ----------
461	export function AnswerDrawer({ drawer, agentSessions, notes, citedObs, onClose, onSaveNote, onDeleteNote, onTogglePin, onCite }: {
462	  drawer: { type: 'agent' | 'note'; id: string } | null;
463	  agentSessions: AgentSession[];
464	  notes: Note[];
465	  citedObs: Record<string, VObservation>;
466	  onClose: () => void;
467	  onSaveNote: (s: AgentSession) => void;
468	  onDeleteNote: (id: string) => void;
469	  onTogglePin: (id: string) => void;
470	  onCite: (id: number | string) => void;
471	}) {
472	  if (!drawer) return null;
473	
474	  let title: string;
475	  let blocks: NoteBlock[];
476	  let animate = false;
477	  let isNote = false;
478	  let noteSaved = false;
479	  let session: AgentSession | null = null;
480	  let note: Note | null = null;
481	  if (drawer.type === 'agent') {
482	    session = agentSessions.find((s) => s.id === drawer.id) || null;
483	    if (!session || !session.answer) return null;
484	    title = session.query;
485	    blocks = session.answer.blocks;
486	    animate = !session.viewed;
487	    noteSaved = !!session.saved;
488	  } else {
489	    note = notes.find((n) => n.id === drawer.id) || null;
490	    if (!note) return null;
491	    title = note.title;
492	    blocks = note.blocks;
493	    isNote = true;
494	  }
495	
496	  return (
497	    <aside className="drawer" data-screen-label={isNote ? 'Note' : 'Agent answer'}>
498	      <div className="drawer-head">
499	        <span className={`drawer-glyph${isNote ? ' note' : ''}`}>
500	          <Icon name={isNote ? 'stickyNote' : 'sparkles'} size={17} />
501	        </span>
502	        <div className="drawer-head-text">
503	          <p className="drawer-eyebrow">{isNote ? 'Saved note' : 'Your agent answered'}</p>
504	          <h3 className="drawer-title">{title}</h3>
505	        </div>
506	        <button className="icon-btn" onClick={onClose} aria-label="Close panel"><Icon name="x" size={16} /></button>
507	      </div>
508	
509	      <div className="drawer-body">
510	        <StreamedBlocks blocks={blocks} animate={animate} citedObs={citedObs} onCite={onCite} />
511	      </div>
512	
513	      <div className="drawer-foot">
514	        {isNote && note ? (
515	          <>
516	            <span className="drawer-foot-meta">Saved {fmtDayLabel(note.created).lead.toLowerCase() === 'today' ? 'today' : fmtDayLabel(note.created).rest}</span>
517	            <button className="btn-ghost" onClick={() => onTogglePin(note!.id)}>
518	              <Icon name="bookmark" size={14} /> {note.pinned ? 'Unpin' : 'Pin to top'}
519	            </button>
520	            <button className="btn-ghost danger" onClick={() => onDeleteNote(note!.id)}>
521	              <Icon name="trash" size={14} /> Delete
522	            </button>
523	          </>
524	        ) : (
525	          <>
526	            <button className="btn-ghost" onClick={onClose}>Dismiss</button>
527	            <button
528	              className={`btn-primary${noteSaved ? ' saved' : ''}`}
529	              onClick={() => !noteSaved && session && onSaveNote(session)}
530	            >
531	              <Icon name={noteSaved ? 'check' : 'stickyNote'} size={15} />
532	              {noteSaved ? 'Saved to notes' : 'Save as note'}
533	            </button>
534	          </>
535	        )}
536	      </div>
537	    </aside>
538	  );
539	}
