'use client';

// ============================================================
// cmem cloud viewer — search, "Ask Your Agent" background sessions, Notes
// The agent answer is synthesized client-side from the loaded memories
// (an instant local recall + compose over the user's own observations).
// (ported from cmem-viewer-pro/cmem-viewer/search-agent.jsx)
// ============================================================
import * as React from 'react';
import { Icon, TYPE_META, fmtDayLabel, baseName, dirName } from './format';
import type { ViewerData, VObservation, Note, NoteBlock } from './types';

const LOGO = '/cmem-viewer-logo.jpg';

export interface AgentAnswer { cited: (number | string)[]; blocks: NoteBlock[] }
export interface AgentSession {
  id: string;
  query: string;
  status: 'running' | 'done';
  stage: string;
  answer: AgentAnswer | null;
  viewed: boolean;
  saved?: boolean;
}

const STOPWORDS = new Set(['the', 'a', 'an', 'and', 'or', 'for', 'with', 'how', 'what', 'why', 'does', 'did', 'is', 'are', 'was', 'were', 'do', 'we', 'our', 'you', 'your', 'when', 'where', 'that', 'this', 'about', 'work', 'works']);

function tokenize(q: string): string[] {
  return q.toLowerCase().split(/[^a-z0-9-]+/).filter((t) => t.length > 2 && !STOPWORDS.has(t));
}

function scoreText(tokens: string[], text: string, weight: number): number {
  if (!text) return 0;
  const lower = text.toLowerCase();
  let s = 0;
  tokens.forEach((t) => { if (lower.includes(t)) s += weight; });
  return s;
}

function scoreObservation(tokens: string[], o: VObservation): number {
  return scoreText(tokens, o.title, 3)
    + scoreText(tokens, (o.concepts || []).join(' '), 3)
    + scoreText(tokens, o.subtitle, 2)
    + scoreText(tokens, (o.facts || []).join(' '), 2)
    + scoreText(tokens, o.narrative, 1)
    + scoreText(tokens, (o.files_read || []).concat(o.files_modified || []).join(' '), 2);
}

export interface SearchResult {
  observations: VObservation[];
  files: [string, number][];
  concepts: string[];
}

// Instant string-match search across the loaded memories
export function searchMemory(query: string, data: ViewerData): SearchResult {
  const tokens = tokenize(query);
  const raw = query.trim().toLowerCase();
  if (!raw) return { observations: [], files: [], concepts: [] };

  const scored = data.observations
    .map((o) => ({ o, s: scoreObservation(tokens.length ? tokens : [raw], o) }))
    .filter((x) => x.s > 0)
    .sort((a, b) => b.s - a.s || b.o.at - a.o.at);

  const fileSet = new Map<string, number>();
  data.observations.forEach((o) => {
    (o.files_read || []).concat(o.files_modified || []).forEach((f) => {
      if (f.toLowerCase().includes(raw) || tokens.some((t) => f.toLowerCase().includes(t))) {
        fileSet.set(f, (fileSet.get(f) || 0) + 1);
      }
    });
  });

  const conceptSet = new Map<string, number>();
  data.observations.forEach((o) => {
    (o.concepts || []).forEach((c) => {
      if (c.includes(raw) || tokens.some((t) => c.includes(t))) {
        conceptSet.set(c, (conceptSet.get(c) || 0) + 1);
      }
    });
  });

  return {
    observations: scored.slice(0, 5).map((x) => x.o),
    files: [...fileSet.entries()].sort((a, b) => b[1] - a[1]).slice(0, 4),
    concepts: [...conceptSet.entries()].sort((a, b) => b[1] - a[1]).slice(0, 6).map((e) => e[0]),
  };
}

// ---------- Agent answer synthesis ----------
export function synthesizeAnswer(query: string, data: ViewerData): AgentAnswer {
  const tokens = tokenize(query);
  const scored = data.observations
    .map((o) => ({ o, s: scoreObservation(tokens, o) }))
    .filter((x) => x.s > 0)
    .sort((a, b) => b.s - a.s || b.o.at - a.o.at)
    .slice(0, 5);

  if (scored.length === 0) {
    return {
      cited: [],
      blocks: [
        { kind: 'p', text: `I went through all ${data.observations.length.toLocaleString()} observations and nothing matches “${query}” yet. Either we haven’t worked on this, or it’s phrased differently in memory.` },
        { kind: 'p', text: 'Try a concept chip from the filter bar, or rephrase with a file name or identifier — exact symbols match best.' },
      ],
    };
  }

  const top = scored.map((x) => x.o);
  const projects = [...new Set(top.map((o) => o.project))];
  const latest = top.reduce((a, b) => (a.at > b.at ? a : b));
  const latestDay = fmtDayLabel(latest.at);
  const sessionsById = Object.fromEntries(data.sessions.map((s) => [s.id, s]));
  const latestSession = sessionsById[latest.session_id];

  const bullets: string[] = [];
  top.forEach((o) => {
    const best = (o.facts || [])
      .map((f) => ({ f, s: scoreText(tokens, f, 1) }))
      .sort((a, b) => b.s - a.s)[0];
    if (best) bullets.push(best.f);
  });

  const blocks: NoteBlock[] = [
    { kind: 'p', text: `I found ${top.length} ${top.length === 1 ? 'memory' : 'memories'} about “${query}” across ${projects.join(' and ')} — most recently “${latest.title}” from ${latestDay.lead.toLowerCase() === 'today' || latestDay.lead.toLowerCase() === 'yesterday' ? latestDay.lead.toLowerCase() : latestDay.rest}.` },
    { kind: 'bullets', items: bullets.slice(0, 4) },
  ];
  if (latestSession && latestSession.next_steps) {
    blocks.push({ kind: 'p', text: `Open thread from that work: ${latestSession.next_steps}` });
  }
  blocks.push({ kind: 'cite', ids: top.map((o) => o.id) });
  return { cited: top.map((o) => o.id), blocks };
}

// ---------- Background agent sessions ----------
export function useAgentSessions(data: ViewerData) {
  const [sessions, setSessions] = React.useState<AgentSession[]>([]);
  const idRef = React.useRef(0);

  const ask = React.useCallback((query: string) => {
    const id = `agent-${++idRef.current}-${Date.now()}`;
    const matches = searchMemory(query, data).observations.length;
    setSessions((prev) => [...prev, { id, query, status: 'running', stage: 'Searching memory…', answer: null, viewed: false }]);

    const stages: [number, string][] = [
      [900, `Reading ${Math.max(matches, 2)} observations…`],
      [2300, 'Composing answer…'],
    ];
    stages.forEach(([delay, stage]) => {
      setTimeout(() => {
        setSessions((prev) => prev.map((s) => (s.id === id && s.status === 'running' ? { ...s, stage } : s)));
      }, delay);
    });
    setTimeout(() => {
      const answer = synthesizeAnswer(query, data);
      setSessions((prev) => prev.map((s) => (s.id === id ? { ...s, status: 'done', stage: 'Answer ready', answer } : s)));
    }, 3600);
    return id;
  }, [data]);

  const dismiss = React.useCallback((id: string) => {
    setSessions((prev) => prev.filter((s) => s.id !== id));
  }, []);

  const markViewed = React.useCallback((id: string) => {
    setSessions((prev) => prev.map((s) => (s.id === id ? { ...s, viewed: true } : s)));
  }, []);

  return { sessions, ask, dismiss, markViewed };
}

// ---------- Notes (persisted) ----------
// Notes hold memory excerpts, so the key MUST be scoped per user — an unscoped
// key would show one account's saved answers to the next account on a shared browser.
const NOTES_KEY_BASE = 'cmem-viewer-notes-v2';

export function useNotes(seedNotes: Note[], userId?: string | null) {
  const notesKey = userId ? `${NOTES_KEY_BASE}:${userId}` : NOTES_KEY_BASE;
  const [notes, setNotes] = React.useState<Note[]>(() => {
    try {
      const raw = localStorage.getItem(notesKey);
      if (raw) {
        const arr = JSON.parse(raw);
        if (Array.isArray(arr) && arr.length) return arr;
      }
    } catch { /* ignore */ }
    return seedNotes;
  });

  React.useEffect(() => {
    try { localStorage.setItem(notesKey, JSON.stringify(notes)); } catch { /* ignore */ }
  }, [notes, notesKey]);

  const saveNote = React.useCallback((note: Omit<Note, 'id' | 'created' | 'pinned'>) => {
    setNotes((prev) => [{ ...note, id: `note-${Date.now()}`, created: Math.floor(Date.now() / 1000), pinned: false }, ...prev]);
  }, []);

  const deleteNote = React.useCallback((id: string) => {
    setNotes((prev) => prev.filter((n) => n.id !== id));
  }, []);

  const togglePin = React.useCallback((id: string) => {
    setNotes((prev) => prev.map((n) => (n.id === id ? { ...n, pinned: !n.pinned } : n)));
  }, []);

  return { notes, saveNote, deleteNote, togglePin };
}

// ---------- Search bar with instant results ----------
export function SearchBar({ data, onAsk, onJump, onFile, onConcept }: {
  data: ViewerData;
  onAsk: (q: string) => void;
  onJump: (id: number | string) => void;
  onFile: (f: string) => void;
  onConcept: (c: string) => void;
}) {
  const [query, setQuery] = React.useState('');
  const [open, setOpen] = React.useState(false);
  const wrapRef = React.useRef<HTMLDivElement>(null);
  const inputRef = React.useRef<HTMLInputElement>(null);

  const results = React.useMemo(() => searchMemory(query, data), [query, data]);
  const hasQuery = query.trim().length > 0;

  React.useEffect(() => {
    const onDocClick = (e: MouseEvent) => {
      if (wrapRef.current && !wrapRef.current.contains(e.target as Node)) setOpen(false);
    };
    const onKey = (e: KeyboardEvent) => {
      const active = document.activeElement as HTMLElement | null;
      if (e.key === '/' && active !== inputRef.current
          && !['INPUT', 'TEXTAREA'].includes(active?.tagName || '')) {
        e.preventDefault();
        inputRef.current?.focus();
      }
    };
    document.addEventListener('mousedown', onDocClick);
    document.addEventListener('keydown', onKey);
    return () => {
      document.removeEventListener('mousedown', onDocClick);
      document.removeEventListener('keydown', onKey);
    };
  }, []);

  const fireAsk = () => {
    if (!hasQuery) return;
    onAsk(query.trim());
    setQuery('');
    setOpen(false);
    inputRef.current?.blur();
  };

  return (
    <div className="search-wrap" ref={wrapRef}>
      <div className={`search-pill${open && hasQuery ? ' engaged' : ''}`}>
        <Icon name="search" size={19} className="search-glyph" />
        <input
          ref={inputRef}
          type="text"
          value={query}
          placeholder="Search your memory…"
          onChange={(e) => { setQuery(e.target.value); setOpen(true); }}
          onFocus={() => setOpen(true)}
          onKeyDown={(e) => {
            if (e.key === 'Enter') fireAsk();
            if (e.key === 'Escape') { setOpen(false); (e.target as HTMLInputElement).blur(); }
          }}
        />
        {hasQuery
          ? <button className="search-clear" onClick={() => { setQuery(''); inputRef.current?.focus(); }} aria-label="Clear search"><Icon name="x" size={14} /></button>
          : <kbd className="search-kbd">/</kbd>}
      </div>

      {open && hasQuery && (
        <div className="search-drop">
          <button className="ask-row" onClick={fireAsk}>
            <span className="ask-glyph"><Icon name="sparkles" size={16} /></span>
            <span className="ask-text">Ask your agent: <em>“{query.trim()}”</em></span>
            <span className="ask-hint">runs in background · ⏎</span>
          </button>

          {results.observations.length > 0 && (
            <div className="drop-section">
              <p className="drop-label">Memories</p>
              {results.observations.map((o) => {
                const m = TYPE_META[o.type] || TYPE_META.feature;
                return (
                  <button key={o.id} className="drop-row" onClick={() => { onJump(o.id); setOpen(false); setQuery(''); }}>
                    <span className="obs-type-bubble sm" data-type={o.type} style={{ background: m.bg, color: m.fg }}><Icon name={m.icon} size={12} /></span>
                    <span className="drop-row-title">{o.title}</span>
                    <span className="drop-row-meta">{o.project} · {fmtDayLabel(o.at).lead}</span>
                  </button>
                );
              })}
            </div>
          )}

          {results.files.length > 0 && (
            <div className="drop-section">
              <p className="drop-label">Files</p>
              {results.files.map(([f, n]) => (
                <button key={f} className="drop-row" onClick={() => { onFile(f); setOpen(false); setQuery(''); }}>
                  <span className="drop-file-glyph"><Icon name="fileCode" size={14} /></span>
                  <span className="drop-row-title mono">{baseName(f)}<span className="drop-dir">{dirName(f)}</span></span>
                  <span className="drop-row-meta">{n} {n === 1 ? 'memory' : 'memories'}</span>
                </button>
              ))}
            </div>
          )}

          {results.concepts.length > 0 && (
            <div className="drop-section">
              <p className="drop-label">Concepts</p>
              <div className="drop-concepts">
                {results.concepts.map((c) => (
                  <button key={c} className="concept-chip" onClick={() => { onConcept(c); setOpen(false); setQuery(''); }}>{c}</button>
                ))}
              </div>
            </div>
          )}

          {results.observations.length === 0 && results.files.length === 0 && results.concepts.length === 0 && (
            <p className="drop-empty">No instant matches — ask your agent instead.</p>
          )}
        </div>
      )}
    </div>
  );
}

// ---------- Background-session toasts ----------
export function AgentToasts({ sessions, onOpen, onDismiss }: {
  sessions: AgentSession[];
  onOpen: (id: string) => void;
  onDismiss: (id: string) => void;
}) {
  const visible = sessions;
  if (visible.length === 0) return null;
  return (
    <div className="agent-toasts">
      {visible.map((s) => (
        <div key={s.id} className={`agent-toast${s.status === 'done' ? ' done' : ''}`}>
          {/* eslint-disable-next-line @next/next/no-img-element */}
          <img src={LOGO} alt="" className={`toast-mark${s.status === 'running' ? ' spin' : ''}`} />
          <button
            className="toast-main"
            onClick={() => s.status === 'done' && onOpen(s.id)}
            disabled={s.status !== 'done'}
          >
            <span className="toast-query">“{s.query}”</span>
            <span className={`toast-stage${s.status === 'done' && !s.viewed ? ' ready' : ''}`}>
              {s.status === 'done' ? (s.viewed ? 'Answer · tap to reopen' : 'Answer ready — tap to read') : s.stage}
            </span>
          </button>
          <button className="toast-x" onClick={() => onDismiss(s.id)} aria-label="Dismiss"><Icon name="x" size={13} /></button>
        </div>
      ))}
    </div>
  );
}

// ---------- Streaming block renderer ----------
type RenderedBlock =
  | { kind: 'p'; text: string }
  | { kind: 'bullets'; items: string[] }
  | { kind: 'cite'; ids: (number | string)[] };

// Word-budget "typing" clip, computed as a pure pass so no render-scope
// variable is mutated during render (compiler-safe).
function clipBlocks(blocks: NoteBlock[], shown: number): RenderedBlock[] {
  const out: RenderedBlock[] = [];
  let budget = shown;
  const clip = (text: string) => {
    const words = text.split(' ');
    if (budget >= words.length) { budget -= words.length; return text; }
    const o = words.slice(0, Math.max(0, budget)).join(' ');
    budget = 0;
    return o;
  };
  for (let i = 0; i < blocks.length; i++) {
    const b = blocks[i];
    if (budget <= 0 && shown !== Infinity && i > 0) break;
    if (b.kind === 'p') {
      const t = shown === Infinity ? (b.text || '') : clip(b.text || '');
      if (t) out.push({ kind: 'p', text: t });
    } else if (b.kind === 'bullets') {
      const items: string[] = [];
      for (const it of (b.items || [])) {
        const t = shown === Infinity ? it : clip(it);
        if (t) items.push(t);
        if (budget <= 0 && shown !== Infinity) break;
      }
      if (items.length) out.push({ kind: 'bullets', items });
    } else if (b.kind === 'cite' && (shown === Infinity || budget > 0)) {
      out.push({ kind: 'cite', ids: b.ids || [] });
    }
  }
  return out;
}

function StreamedBlocks({ blocks, animate, citedObs, onCite }: {
  blocks: NoteBlock[];
  animate: boolean;
  citedObs: Record<string, VObservation>;
  onCite: (id: number | string) => void;
}) {
  const totalWords = React.useMemo(
    () => blocks.reduce((n, b) => n + (b.kind === 'p' ? (b.text || '').split(' ').length : b.kind === 'bullets' ? (b.items || []).join(' ').split(' ').length : 1), 0),
    [blocks],
  );
  const [shown, setShown] = React.useState(animate ? 0 : Infinity);

  React.useEffect(() => {
    if (!animate) { setShown(Infinity); return undefined; }
    setShown(0);
    let count = 0;
    const iv = setInterval(() => {
      count += 3;
      setShown(count);
      if (count >= totalWords + 5) clearInterval(iv);
    }, 50);
    return () => clearInterval(iv);
  }, [animate, blocks, totalWords]);

  const rendered = clipBlocks(blocks, shown);

  return (
    <div className="answer-blocks">
      {rendered.map((b, i) => {
        if (b.kind === 'p') {
          return <p key={i} className="answer-p">{b.text}</p>;
        }
        if (b.kind === 'bullets') {
          return <ul key={i} className="answer-bullets">{b.items.map((it, j) => <li key={j}>{it}</li>)}</ul>;
        }
        return (
          <div key={i} className="answer-cites">
            <p className="drop-label">From memory</p>
            <div className="cite-chips">
              {b.ids.map((id) => {
                const o = citedObs[id];
                if (!o) return null;
                const m = TYPE_META[o.type] || TYPE_META.feature;
                return (
                  <button key={id} className="cite-chip" onClick={() => onCite(id)}>
                    <span className="obs-type-bubble sm" data-type={o.type} style={{ background: m.bg, color: m.fg }}><Icon name={m.icon} size={11} /></span>
                    <span>#{id} {o.title}</span>
                  </button>
                );
              })}
            </div>
          </div>
        );
      })}
    </div>
  );
}

// ---------- Right drawer: agent answer or saved note ----------
export function AnswerDrawer({ drawer, agentSessions, notes, citedObs, onClose, onSaveNote, onDeleteNote, onTogglePin, onCite }: {
  drawer: { type: 'agent' | 'note'; id: string } | null;
  agentSessions: AgentSession[];
  notes: Note[];
  citedObs: Record<string, VObservation>;
  onClose: () => void;
  onSaveNote: (s: AgentSession) => void;
  onDeleteNote: (id: string) => void;
  onTogglePin: (id: string) => void;
  onCite: (id: number | string) => void;
}) {
  if (!drawer) return null;

  let title: string;
  let blocks: NoteBlock[];
  let animate = false;
  let isNote = false;
  let noteSaved = false;
  let session: AgentSession | null = null;
  let note: Note | null = null;
  if (drawer.type === 'agent') {
    session = agentSessions.find((s) => s.id === drawer.id) || null;
    if (!session || !session.answer) return null;
    title = session.query;
    blocks = session.answer.blocks;
    animate = !session.viewed;
    noteSaved = !!session.saved;
  } else {
    note = notes.find((n) => n.id === drawer.id) || null;
    if (!note) return null;
    title = note.title;
    blocks = note.blocks;
    isNote = true;
  }

  return (
    <aside className="drawer" data-screen-label={isNote ? 'Note' : 'Agent answer'}>
      <div className="drawer-head">
        <span className={`drawer-glyph${isNote ? ' note' : ''}`}>
          <Icon name={isNote ? 'stickyNote' : 'sparkles'} size={17} />
        </span>
        <div className="drawer-head-text">
          <p className="drawer-eyebrow">{isNote ? 'Saved note' : 'Your agent answered'}</p>
          <h3 className="drawer-title">{title}</h3>
        </div>
        <button className="icon-btn" onClick={onClose} aria-label="Close panel"><Icon name="x" size={16} /></button>
      </div>

      <div className="drawer-body">
        <StreamedBlocks blocks={blocks} animate={animate} citedObs={citedObs} onCite={onCite} />
      </div>

      <div className="drawer-foot">
        {isNote && note ? (
          <>
            <span className="drawer-foot-meta">Saved {fmtDayLabel(note.created).lead.toLowerCase() === 'today' ? 'today' : fmtDayLabel(note.created).rest}</span>
            <button className="btn-ghost" onClick={() => onTogglePin(note!.id)}>
              <Icon name="bookmark" size={14} /> {note.pinned ? 'Unpin' : 'Pin to top'}
            </button>
            <button className="btn-ghost danger" onClick={() => onDeleteNote(note!.id)}>
              <Icon name="trash" size={14} /> Delete
            </button>
          </>
        ) : (
          <>
            <button className="btn-ghost" onClick={onClose}>Dismiss</button>
            <button
              className={`btn-primary${noteSaved ? ' saved' : ''}`}
              onClick={() => !noteSaved && session && onSaveNote(session)}
            >
              <Icon name={noteSaved ? 'check' : 'stickyNote'} size={15} />
              {noteSaved ? 'Saved to notes' : 'Save as note'}
            </button>
          </>
        )}
      </div>
    </aside>
  );
}

