    ['path', { d: 'M12.22 2h-.44a2 2 0 0 0-2 2v.18a2 2 0 0 1-1 1.73l-.43.25a2 2 0 0 1-2 0l-.15-.08a2 2 0 0 0-2.73.73l-.22.38a2 2 0 0 0 .73 2.73l.15.1a2 2 0 0 1 1 1.72v.51a2 2 0 0 1-1 1.74l-.15.09a2 2 0 0 0-.73 2.73l.22.38a2 2 0 0 0 2.73.73l.15-.08a2 2 0 0 1 2 0l.43.25a2 2 0 0 1 1 1.73V20a2 2 0 0 0 2 2h.44a2 2 0 0 0 2-2v-.18a2 2 0 0 1 1-1.73l.43-.25a2 2 0 0 1 2 0l.15.08a2 2 0 0 0 2.73-.73l.22-.39a2 2 0 0 0-.73-2.73l-.15-.08a2 2 0 0 1-1-1.74v-.5a2 2 0 0 1 1-1.74l.15-.09a2 2 0 0 0 .73-2.73l-.22-.38a2 2 0 0 0-2.73-.73l-.15.08a2 2 0 0 1-2 0l-.43-.25a2 2 0 0 1-1-1.73V4a2 2 0 0 0-2-2z' }],
    ['circle', { cx: 12, cy: 12, r: 3 }]
  ]
};

export function Icon({
  name, size = 18, strokeWidth = 2, style, className,
}: {
  name: string;
  size?: number;
  strokeWidth?: number;
  style?: React.CSSProperties;
  className?: string;
}) {
  const nodes = ICON_PATHS[name] || [];
  return (
    <svg
      width={size} height={size} viewBox="0 0 24 24" fill="none"
      stroke="currentColor" strokeWidth={strokeWidth}
      strokeLinecap="round" strokeLinejoin="round"
      style={style} className={className} aria-hidden="true"
    >
      {nodes.map(([tag, attrs], i) => React.createElement(tag, { key: i, ...attrs }))}
    </svg>
  );
}

// ---------- Observation type metadata ----------
export const TYPE_META: Record<string, { icon: string; label: string; fg: string; bg: string }> = {
  feature:   { icon: 'zap',       label: 'feature',   fg: '#D6532F', bg: '#FFE0D2' },
  bugfix:    { icon: 'bug',       label: 'bugfix',    fg: '#C03A28', bg: '#FBE2DD' },
  refactor:  { icon: 'wrench',    label: 'refactor',  fg: '#3E76B5', bg: '#E3EEFA' },
  discovery: { icon: 'lightbulb', label: 'discovery', fg: '#B97714', bg: '#FDEFD6' },
  decision:  { icon: 'gitBranch', label: 'decision',  fg: '#3E7E55', bg: '#E6F3EA' },
};

// ---------- formatting helpers ----------
export const fmtTime = (epoch: number) =>
  new Date(epoch * 1000).toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' });

export const fmtDayKey = (epoch: number) => {
  const d = new Date(epoch * 1000);
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
};

export const fmtDayLabel = (epoch: number) => {
  const d = new Date(epoch * 1000);
  const now = new Date();
  const today = fmtDayKey(now.getTime() / 1000);
  const yest = fmtDayKey(now.getTime() / 1000 - 86400);
  const key = fmtDayKey(epoch);
  const label = d.toLocaleDateString([], { weekday: 'long', month: 'long', day: 'numeric' });
  if (key === today) return { lead: 'Today', rest: label };
  if (key === yest) return { lead: 'Yesterday', rest: label };
  return { lead: d.toLocaleDateString([], { weekday: 'long' }), rest: d.toLocaleDateString([], { month: 'long', day: 'numeric' }) };
};

export const baseName = (path: string) => path.split('/').pop() as string;
export const dirName = (path: string) => {
  const parts = path.split('/');
  return parts.slice(0, -1).join('/');
};

