'use client';

// ============================================================
// cmem cloud viewer — header controls
// useTheme (light / dark / system, persisted to localStorage)
// + ThemeToggle (segmented) + SettingsMenu (popover)
// + useTweaks (density / accent / roundness, persisted).
// (ported from cmem-viewer-pro/cmem-viewer/header-controls.jsx
//  and the useTweaks contract from tweaks-panel.jsx)
// ============================================================
import * as React from 'react';
import { Icon } from './format';
import { signOut } from '@/lib/auth-client';
import type { Tweaks, LiveState } from './types';

// ---------- accent palette (single source — CloudViewer derives surfaces from it) ----------
export const ACCENTS: Record<string, { a: string; deep: string; soft: string; tint: string }> = {
  coral: { a: '#FF6B47', deep: '#F2543D', soft: '#FFE0D2', tint: '#FFF1EB' },
  ember: { a: '#F2543D', deep: '#D63E2C', soft: '#FFD9CE', tint: '#FFEEE8' },
  honey: { a: '#F59A3C', deep: '#DD7F1E', soft: '#FFE5C2', tint: '#FFF4E4' },
};

// ---------- tweaks (density / accent / roundness) ----------
const TWEAKS_KEY = 'cmem-viewer-tweaks';

export function useTweaks(defaults: Tweaks): [Tweaks, (key: keyof Tweaks, val: Tweaks[keyof Tweaks]) => void] {
  const [values, setValues] = React.useState<Tweaks>(() => {
    try {
      const raw = localStorage.getItem(TWEAKS_KEY);
      if (raw) return { ...defaults, ...JSON.parse(raw) };
    } catch { /* storage unavailable */ }
    return defaults;
  });

  const setTweak = React.useCallback((key: keyof Tweaks, val: Tweaks[keyof Tweaks]) => {
    setValues((prev) => {
      const next = { ...prev, [key]: val };
      try { localStorage.setItem(TWEAKS_KEY, JSON.stringify(next)); } catch { /* ignore */ }
      return next;
    });
  }, []);

  return [values, setTweak];
}

// ---------- theme ----------
export function useTheme(): [string, (v: string) => void, 'light' | 'dark'] {
  const read = () => {
    try {
      // 'theme' is the old dashboard's key — honor it so explicit choices survive the upgrade
      const v = localStorage.getItem('cmem-theme') || localStorage.getItem('theme') || 'system';
      return v === 'light' || v === 'dark' ? v : 'system';
    } catch { return 'system'; }
  };
  const [theme, setThemeState] = React.useState<string>(read);
  const sysDark = () => !!(window.matchMedia && window.matchMedia('(prefers-color-scheme: dark)').matches);
  const [systemDark, setSystemDark] = React.useState(sysDark);

  // follow the OS when in 'system' mode
  React.useEffect(() => {
    if (!window.matchMedia) return undefined;
    const mq = window.matchMedia('(prefers-color-scheme: dark)');
    const onChange = () => setSystemDark(mq.matches);
    if (mq.addEventListener) mq.addEventListener('change', onChange);
    else mq.addListener(onChange);
    return () => {
      if (mq.removeEventListener) mq.removeEventListener('change', onChange);
      else mq.removeListener(onChange);
    };
  }, []);

  const resolved: 'light' | 'dark' = theme === 'system' ? (systemDark ? 'dark' : 'light') : (theme as 'light' | 'dark');

  React.useEffect(() => {
    document.documentElement.setAttribute('data-theme', resolved);
  }, [resolved]);

  const setTheme = React.useCallback((v: string) => {
    setThemeState(v);
    try { localStorage.setItem('cmem-theme', v); } catch { /* ignore */ }
  }, []);

  return [theme, setTheme, resolved];
}

// ---------- segmented light / system / dark toggle ----------
export function ThemeToggle({ theme, setTheme }: { theme: string; setTheme: (v: string) => void }) {
  const opts = [
    { v: 'light', icon: 'sun', label: 'Light' },
    { v: 'system', icon: 'monitor', label: 'System' },
    { v: 'dark', icon: 'moon', label: 'Dark' },
  ];
  return (
    <div className="theme-seg" role="radiogroup" aria-label="Color theme">
      {opts.map((o) => (
        <button
          key={o.v}
          type="button"
          role="radio"
          aria-checked={theme === o.v}
          className={`theme-seg-btn${theme === o.v ? ' active' : ''}`}
          onClick={() => setTheme(o.v)}
          title={`${o.label} theme`}
          aria-label={`${o.label} theme`}
        >
          <Icon name={o.icon} size={15} />
        </button>
      ))}
    </div>
  );
}

// ---------- settings popover ----------
export function SettingsMenu({ t, setTweak, live }: {
  t: Tweaks;
  setTweak: (key: keyof Tweaks, val: Tweaks[keyof Tweaks]) => void;
  live: LiveState;
}) {
  const [open, setOpen] = React.useState(false);
  const ref = React.useRef<HTMLDivElement>(null);

  React.useEffect(() => {
    if (!open) return undefined;
    const onDoc = (e: MouseEvent) => { if (ref.current && !ref.current.contains(e.target as Node)) setOpen(false); };
    const onKey = (e: KeyboardEvent) => { if (e.key === 'Escape') setOpen(false); };
    document.addEventListener('mousedown', onDoc);
    document.addEventListener('keydown', onKey);
    return () => {
      document.removeEventListener('mousedown', onDoc);
      document.removeEventListener('keydown', onKey);
    };
  }, [open]);

  // connection state (kept compact here rather than a header pill)
  const cs = live.status === 'live'
    ? (live.streamOk ? 'ok' : 'warn')
    : live.status === 'connecting' ? 'warn' : 'err';
  const clabel = live.status === 'live'
    ? (live.streamOk ? 'Live' : 'Reconnecting…')
    : live.status === 'connecting' ? 'Connecting…' : 'Offline';
  const processing = live.isLive && live.proc && live.proc.isProcessing;

  return (
    <div className="settings-wrap" ref={ref}>
      <button
        type="button"
        className={`settings-btn${open ? ' on' : ''}`}
        onClick={() => setOpen((o) => !o)}
        title="Settings"
        aria-label="Settings"
        aria-haspopup="dialog"
        aria-expanded={open}
      >
        <Icon name="settings" size={17} />
      </button>

      {open && (
        <div className="settings-pop" role="dialog" aria-label="Settings">
          <div className="set-head"><Icon name="settings" size={14} /> Settings</div>

          <div className="set-section">Appearance</div>

          <div className="set-row">
            <span className="set-label">Density</span>
            <div className="set-seg" role="radiogroup" aria-label="Density">
              {(['cozy', 'compact'] as const).map((d) => (
                <button
                  key={d}
                  type="button"
                  role="radio"
                  aria-checked={t.density === d}
                  className={`set-seg-btn${t.density === d ? ' active' : ''}`}
                  onClick={() => setTweak('density', d)}
                >{d}</button>
              ))}
            </div>
          </div>

          <div className="set-row col">
            <div className="set-label-row">
              <span className="set-label">Roundness</span>
              <span className="set-val">{Math.round(t.roundness * 100)}%</span>
            </div>
            <input
              type="range"
              className="set-slider"
              min={0.6} max={1.25} step={0.05}
              value={t.roundness}
              onChange={(e) => setTweak('roundness', Number(e.target.value))}
              aria-label="Corner roundness"
            />
          </div>

          <div className="set-row">
            <span className="set-label">Accent</span>
            <div className="set-swatches" role="radiogroup" aria-label="Accent color">
              {Object.values(ACCENTS).map(({ a: c }) => (
                <button
                  key={c}
                  type="button"
                  role="radio"
                  aria-checked={t.accent === c}
                  className={`set-swatch${t.accent === c ? ' active' : ''}`}
                  style={{ background: c }}
                  onClick={() => setTweak('accent', c)}
                  aria-label={`Accent ${c}`}
                >
                  {t.accent === c && <Icon name="check" size={12} />}
                </button>
              ))}
            </div>
          </div>

          <div className="set-divider"></div>

          <div className="set-conn">
            <span className={`set-conn-dot ${cs}`}></span>
            <span className="set-conn-label">{clabel}</span>
            {processing && (
              <span className="set-conn-meta">
                processing{live.proc.queueDepth > 0 ? ` · ${live.proc.queueDepth}` : ''}
              </span>
            )}
            {live.status === 'offline' && (
              <button type="button" className="set-conn-retry" onClick={live.retry}>Retry</button>
            )}
          </div>

          <div className="set-divider"></div>

          <button
            type="button"
            className="set-signout"
            onClick={async () => {
              await signOut();
              window.location.href = '/login';
            }}
          >
            <Icon name="logOut" size={14} /> Sign out
          </button>
        </div>
      )}
    </div>
  );
}

