/* ============================================================
   cmem cloud viewer — ported design-system foundation + app CSS
   Source: cmem-viewer-pro (CMEM Viewer v5)
   ============================================================ */
/* ============================================================
   CMEM AGENT — Colors & Type foundations
   A clean, bubbly, oversized, very soft system.
   Anchored on the coral "anemone" mark and a warm cream world.
   ============================================================ */

/* ---- Webfonts (Google Fonts) -------------------------------
   Fredoka  → bubbly rounded display / wordmark (matches the sticker)
   Nunito   → soft rounded humanist UI + body text
   JetBrains Mono → the agent's terminal / memory tokens / code
   NOTE: substituted from Google Fonts — see README "Typography".
------------------------------------------------------------- */
@import url('https://fonts.googleapis.com/css2?family=Fredoka:wght@400;500;600;700&family=Nunito:ital,wght@0,400;0,500;0,600;0,700;0,800;1,400;1,600&family=JetBrains+Mono:wght@400;500;600&display=swap');
@import url('https://api.fontshare.com/v2/css?f[]=switzer@400,500,600,700&display=swap');

:root {
  /* ---------- BRAND • coral / ember / honey ---------- */
  --coral-50:  #FFF1EB;
  --coral-100: #FFE0D2;
  --coral-200: #FFC2A8;
  --coral-300: #FF9F77;
  --coral-400: #FF8155;   /* tangerine */
  --coral-500: #FF6B47;   /* PRIMARY — the brand coral */
  --coral-600: #F2543D;   /* ember — gradient base of the mark */
  --coral-700: #D63E2C;
  --honey-300: #FFD49B;
  --honey-400: #FFB066;   /* warm amber highlight */
  --honey-500: #F59A3C;
  --peach:     #FBD9BE;   /* the cream wordmark tone on the sticker */

  /* Signature gradient (top→bottom of the anemone) */
  --grad-anemone: linear-gradient(155deg, #FF8A4C 0%, #FF6B47 45%, #F2543D 100%);
  --grad-sunwash: radial-gradient(120% 120% at 50% 0%, #FFE9DC 0%, #FFF8F2 60%);
  --grad-ember-soft: linear-gradient(160deg, #FFEEE4 0%, #FFE0D2 100%);

  /* ---------- WARM NEUTRALS • cream → espresso ---------- */
  --cream-50:  #FFF8F2;   /* app background */
  --cream-100: #FCEFE6;   /* raised surface / sunken wells */
  --sand-200:  #F4E3D6;   /* hairline fills, chips */
  --sand-300:  #E8D5C5;   /* borders */
  --taupe-400: #CDB6A4;   /* disabled, faint */
  --mocha-500: #9E8676;   /* muted text */
  --coffee-700:#5E4A3E;   /* secondary text */
  --espresso-900:#2A1C15; /* primary text — warm near-black */

  /* A deep forest-espresso echoing the sticker background */
  --midnight: #141019;    /* never pure black; cool-warm ink for dark lockups */
  --midnight-soft: #211A2B;

  /* ---------- SEMANTIC ---------- */
  --success: #4F9E6A;   --success-bg: #E6F3EA;
  --warning: #F5A623;   --warning-bg: #FDEFD6;
  --danger:  #E0402E;   --danger-bg:  #FBE2DD;
  --info:    #4C8DD6;   --info-bg:    #E3EEFA;

  /* ---------- SURFACES / TOKENS ---------- */
